import logging
import uuid
from datetime import UTC, datetime

import jwt
import requests
from django.conf import settings
from django.core.cache import cache
from jwt.algorithms import RSAAlgorithm

from care.abdm.service.client import abdm_timestamp
from care.abdm.service.errors import AbdmError
from care.abdm.service.gateway import get_access_token

logger = logging.getLogger(__name__)

OIDC_CONFIG_PATH = "/api/hiecm/gateway/v3/.well-known/openid-configuration"
JWKS_CACHE_KEY = "abdm:gateway:jwks"
JWKS_CACHE_SECONDS = 60 * 60
# RS256 signs the gateway session token callbacks carry; RS512 signs link tokens (sbx B14).
ALGORITHMS = ("RS256", "RS512")


def _gateway_headers() -> dict:
    headers = {
        "REQUEST-ID": str(uuid.uuid4()),
        "TIMESTAMP": abdm_timestamp(),
        "X-CM-ID": settings.ABDM_CM_ID,
    }
    # The certs endpoints once required the gateway token (sbx B14); today they don't.
    try:
        headers["Authorization"] = f"Bearer {get_access_token()}"
    except AbdmError:
        pass
    return headers


def jwks_url() -> str:
    response = requests.get(
        f"{settings.ABDM_GATEWAY_URL}{OIDC_CONFIG_PATH}",
        headers=_gateway_headers(),
        timeout=settings.ABDM_REQUEST_TIMEOUT,
    )
    response.raise_for_status()
    return response.json()["jwks_uri"]


def get_jwks(*, refresh: bool = False) -> dict:
    if not refresh and (cached := cache.get(JWKS_CACHE_KEY)):
        return cached
    response = requests.get(
        jwks_url(), headers=_gateway_headers(), timeout=settings.ABDM_REQUEST_TIMEOUT
    )
    response.raise_for_status()
    jwks = response.json()
    cache.set(JWKS_CACHE_KEY, jwks, timeout=JWKS_CACHE_SECONDS)
    return jwks


def _find_key(kid):
    for refresh in (False, True):
        for jwk in get_jwks(refresh=refresh).get("keys", []):
            if jwk.get("kid") == kid and jwk.get("kty") == "RSA":
                return RSAAlgorithm.from_jwk(json.dumps(jwk))
    return None


def verify_callback(request) -> str:
    """Check the gateway bearer JWT on an inbound callback.

    Returns "ok", "late:<s>s" (signed, expired within the leeway) or
    "failed:<reason>". The JWT authenticates the sender, not the body.
    """
    authorization = request.headers.get("Authorization", "")
    scheme, _, token = authorization.partition(" ")
    if scheme.lower() != "bearer" or not token.strip():
        return "failed:missing bearer"
    token = token.strip()

    try:
        header = jwt.get_unverified_header(token)
    except jwt.PyJWTError:
        return "failed:malformed token"
    algorithm = header.get("alg")
    if algorithm not in ALGORITHMS:
        return "failed:algorithm"

    try:
        key = _find_key(header.get("kid"))
    except (requests.RequestException, ValueError, KeyError) as e:
        logger.warning("ABDM JWKS unavailable: %s", type(e).__name__)
        return "failed:jwks unavailable"
    if key is None:
        return "failed:unknown key"

    try:
        claims = jwt.decode(
            token,
            key,
            algorithms=[algorithm],
            options={"verify_exp": False, "verify_aud": False, "require": ["exp"]},
        )
    except jwt.InvalidSignatureError:
        return "failed:bad signature"
    except jwt.PyJWTError:
        return "failed:invalid token"

    try:
        late = int(datetime.now(UTC).timestamp() - float(claims["exp"]))
    except (TypeError, ValueError):
        return "failed:invalid token"
    if late <= 0:
        return "ok"
    if late <= settings.ABDM_CALLBACK_TOKEN_LEEWAY_SECONDS:
        return f"late:{late}s"
    return f"failed:expired {late}s"
