import logging
from collections.abc import Callable
from dataclasses import dataclass, field

from django.db import transaction
from django.utils import timezone
from rest_framework.response import Response
from rest_framework.views import APIView

from care.abdm.models import AbdmCallback
from care.abdm.service.callbacks import verify_callback
from care.abdm.service.gateway_calls import redacted

logger = logging.getLogger(__name__)

REDACTED_HEADERS = {"authorization", "x-link-token", "cookie"}
MAX_RAW_BODY = 10000

Handler = Callable[[AbdmCallback], None]
_handlers: dict[str, Handler] = {}


def register_callback(route_name: str):
    """Register `handler(callback: AbdmCallback) -> None` for a callback route.

    Runs in a Celery task after the row commits. Raise CallbackNotReady to be
    retried (e.g. the outbound row it answers has not committed yet).
    """

    def decorator(handler: Handler) -> Handler:
        _handlers[route_name] = handler
        return handler

    return decorator


def get_handler(route_name: str) -> Handler | None:
    return _handlers.get(route_name)


class CallbackNotReady(Exception):  # noqa: N818
    pass


class NoHandler(Exception):  # noqa: N818
    pass


def _find(body: dict, *paths: str) -> str:
    for dotted in paths:
        value = body
        for key in dotted.split("."):
            value = value.get(key) if isinstance(value, dict) else None
        if value:
            return str(value)
    return ""


def _parse_body(request) -> dict:
    raw = request.body or b""
    if not raw:
        return {}
    try:
        body = json.loads(raw)
    except (ValueError, UnicodeDecodeError):
        return {"_raw": raw[:MAX_RAW_BODY].decode(errors="replace")}
    return body if isinstance(body, dict) else {"_json": body}


class CallbackView(APIView):
    """Stores an inbound ABDM callback, then processes it in a Celery task."""

    authentication_classes = []
    permission_classes = []
    throttle_classes = []
    response_status = 202
    route_name = ""

    def authenticate_callback(self, request) -> str:
        return verify_callback(request)

    def post(self, request, *args, **kwargs):
        auth_status = self.authenticate_callback(request)
        request_id = request.headers.get("REQUEST-ID", "")[:64]
        if (
            request_id
            and not auth_status.startswith("failed")
            and AbdmCallback.objects.filter(path=request.path, request_id=request_id)
            .exclude(auth_status__startswith="failed")
            .exists()
        ):
            return Response({}, status=self.response_status)

        body = _parse_body(request)
        callback = AbdmCallback.objects.create(
            path=request.path[:255],
            request_id=request_id,
            response_request_id=_find(
                body, "response.requestId", "resp.requestId"
            )[:64],
            transaction_id=_find(
                body, "transactionId", "hiRequest.transactionId"
            )[:128],
            headers={
                key: redacted(value) if key.lower() in REDACTED_HEADERS else value
                for key, value in request.headers.items()
            },
            body=body,
            auth_status=auth_status[:64],
            meta={"route": self.route_name},
        )
        if auth_status.startswith("failed"):
            logger.warning(
                "ABDM callback %s refused: %s REQUEST-ID=%s",
                self.route_name,
                auth_status,
                request_id,
            )
            return Response({}, status=401)

        from care.abdm.tasks import process_callback

        transaction.on_commit(lambda: process_callback.delay(callback.id))
        return Response({}, status=self.response_status)

    def handle(self, callback: AbdmCallback) -> None:
        handler = get_handler(self.route_name)
        if handler is None:
            raise NoHandler
        handler(callback)


def mark_processed(callback: AbdmCallback, error: str = "") -> None:
    callback.processed_at = timezone.now()
    callback.process_error = error
    callback.save(update_fields=["processed_at", "process_error"])


@dataclass
class CallbackRoute:
    view_class: type[CallbackView]
    initkwargs: dict = field(default_factory=dict)


# Filled by callbacks/urls.py: route name -> how to rebuild its view in a task.
ROUTES: dict[str, CallbackRoute] = {}


def dispatch(callback_id: int) -> None:
    """Run a stored callback's handler once. Re-raises CallbackNotReady."""
    from care.abdm.callbacks import urls  # noqa: F401  # populates ROUTES

    callback = AbdmCallback.objects.filter(id=callback_id).first()
    if callback is None or callback.processed_at or not callback.authenticated:
        return
    route = ROUTES.get(callback.meta.get("route", ""))
    if route is None:
        mark_processed(callback, "unknown route")
        return
    try:
        route.view_class(**route.initkwargs).handle(callback)
    except CallbackNotReady:
        raise
    except NoHandler:
        mark_processed(callback, "no handler")
        return
    except Exception as e:
        logger.exception("ABDM callback %s failed", callback.id)
        mark_processed(callback, f"{type(e).__name__}: {e}"[:2000])
        return
    mark_processed(callback)
