from celery.exceptions import MaxRetriesExceededError

from care.abdm.callbacks.base import CallbackNotReady, dispatch, mark_processed
from care.abdm.models import AbdmCallback


@shared_task(bind=True, max_retries=6, default_retry_delay=10)
def process_callback(self, callback_id: int):
    try:
        dispatch(callback_id)
    except CallbackNotReady as e:
        try:
            raise self.retry() from e
        except MaxRetriesExceededError:
            callback = AbdmCallback.objects.filter(id=callback_id).first()
            if callback:
                mark_processed(callback, f"not ready: {e}"[:2000])
