{"content": """"The ECDH scheme ABDM uses to encrypt health records between HIP and HIU.

X25519 key agreement; nonce_xor = nonceA XOR nonceB; HKDF-SHA256(salt =
nonce_xor[:20], info = b"", length 32); AES-GCM with iv = nonce_xor[-12:];
content = base64(ciphertext || tag). The portal leaves the HKDF hash and
info unpublished; these follow the sandbox implementation (sbx H5).
"""

import base64
import os
from dataclasses import dataclass
from datetime import UTC, datetime

from cryptography.exceptions import InvalidTag
from cryptography.fernet import Fernet, InvalidToken
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric.x25519 import (
    X25519PrivateKey,
    X25519PublicKey,
)
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from cryptography.hazmat.primitives.kdf.hkdf import HKDF
from cryptography.hazmat.primitives.serialization import (
    Encoding,
    NoEncryption,
    PrivateFormat,
    PublicFormat,
    load_der_public_key,
)
from django.conf import settings

CRYPTO_ALG = "ECDH"
CURVE = "Curve25519"
PARAMETERS = "Curve25519/32byte random key"
NONCE_BYTES = 32
RAW_KEY_BYTES = 32


class DataflowCryptoError(ValueError):
    pass


@dataclass
class KeyPair:
    private_key: bytes  # raw 32 bytes; encrypt_at_rest() before storing
    public_key_b64: str  # base64 X.509 SubjectPublicKeyInfo DER
    nonce_b64: str


def _b64decode(value: str, what: str) -> bytes:
    try:
        return base64.b64decode(value, validate=True)
    except (ValueError, TypeError) as e:
        raise DataflowCryptoError(f"{what} is not base64") from e


def generate_key_pair() -> KeyPair:
    private = X25519PrivateKey.generate()
    return KeyPair(
        private_key=private.private_bytes(
            Encoding.Raw, PrivateFormat.Raw, NoEncryption()
        ),
        public_key_b64=base64.b64encode(
            private.public_key().public_bytes(
                Encoding.DER, PublicFormat.SubjectPublicKeyInfo
            )
        ).decode(),
        nonce_b64=base64.b64encode(os.urandom(NONCE_BYTES)).decode(),
    )


def _iso(value: datetime) -> str:
    return (
        value.astimezone(UTC).isoformat(timespec="milliseconds").replace("+00:00", "Z")
    )


def key_material(pair: KeyPair, expiry: datetime) -> dict:
    return {
        "cryptoAlg": CRYPTO_ALG,
        "curve": CURVE,
        "dhPublicKey": {
            "expiry": _iso(expiry),
            "parameters": PARAMETERS,
            "keyValue": pair.public_key_b64,
        },
        "nonce": pair.nonce_b64,
    }


def generate_key_material(expiry: datetime) -> tuple[KeyPair, dict]:
    pair = generate_key_pair()
    return pair, key_material(pair, expiry)


def load_public_key(key_value_b64: str) -> X25519PublicKey:
    """Accepts base64 of an X.509 SPKI DER key or of the raw 32 bytes."""
    data = _b64decode(key_value_b64, "keyValue")
    if len(data) == RAW_KEY_BYTES:
        return X25519PublicKey.from_public_bytes(data)
    try:
        key = load_der_public_key(data)
    except ValueError as e:
        raise DataflowCryptoError("keyValue is not an X25519 public key") from e
    if not isinstance(key, X25519PublicKey):
        raise DataflowCryptoError("keyValue is not an X25519 public key")
    return key


def _peer(peer_key_material: dict) -> tuple[X25519PublicKey, bytes]:
    try:
        key_value = peer_key_material["dhPublicKey"]["keyValue"]
        nonce_b64 = peer_key_material["nonce"]
    except (KeyError, TypeError) as e:
        raise DataflowCryptoError("keyMaterial lacks dhPublicKey.keyValue or nonce") from e
    nonce = _b64decode(nonce_b64, "nonce")
    if len(nonce) != NONCE_BYTES:
        raise DataflowCryptoError(f"nonce must be {NONCE_BYTES} bytes")
    return load_public_key(key_value), nonce


def derive_session(
    private_key: bytes, peer_public: X25519PublicKey, own_nonce: bytes, peer_nonce: bytes
) -> tuple[bytes, bytes]:
    """(AES key, GCM iv) for one exchange; symmetric in the two nonces."""
    if len(own_nonce) != NONCE_BYTES or len(peer_nonce) != NONCE_BYTES:
        raise DataflowCryptoError(f"nonces must be {NONCE_BYTES} bytes")
    xor = bytes(a ^ b for a, b in zip(own_nonce, peer_nonce, strict=True))
    shared = X25519PrivateKey.from_private_bytes(private_key).exchange(peer_public)
    key = HKDF(algorithm=hashes.SHA256(), length=32, salt=xor[:20], info=b"").derive(
        shared
    )
    return key, xor[-12:]


def encrypt_for(
    peer_key_material: dict, plaintext: bytes, *, expiry: datetime | None = None
) -> tuple[str, dict]:
    """Encrypt under a fresh key pair; returns (content_b64, our keyMaterial).

    Every call uses a new key pair and nonce, so key and iv are never reused:
    send one entry per keyMaterial.
    """
    peer_public, peer_nonce = _peer(peer_key_material)
    pair, material = generate_key_material(expiry or datetime.now(UTC))
    key, iv = derive_session(
        pair.private_key, peer_public, base64.b64decode(pair.nonce_b64), peer_nonce
    )
    content = AESGCM(key).encrypt(iv, plaintext, None)
    return base64.b64encode(content).decode(), material


def decrypt_from(peer_key_material: dict, own: KeyPair, content_b64: str) -> bytes:
    peer_public, peer_nonce = _peer(peer_key_material)
    key, iv = derive_session(
        own.private_key, peer_public, _b64decode(own.nonce_b64, "nonce"), peer_nonce
    )
    try:
        return AESGCM(key).decrypt(iv, _b64decode(content_b64, "content"), None)
    except InvalidTag as e:
        raise DataflowCryptoError("content failed authentication") from e


def _fernet() -> Fernet:
    key = HKDF(
        algorithm=hashes.SHA256(), length=32, salt=None, info=b"care.abdm.at-rest"
    ).derive(settings.SECRET_KEY.encode())
    return Fernet(base64.urlsafe_b64encode(key))


def encrypt_at_rest(data: bytes) -> str:
    return _fernet().encrypt(data).decode()


def decrypt_at_rest(token: str) -> bytes:
    try:
        return _fernet().decrypt(token.encode())
    except InvalidToken as e:
        raise DataflowCryptoError("stored secret could not be decrypted") from e
