def get_service(service_id: str) -> AbdmOutboundRequest:
    return gateway_call(
        "gateway.bridge_service",
        "GET",
        BRIDGE_SERVICE_PATH.format(service_id=service_id),
    )


def update_bridge_url(url: str) -> AbdmOutboundRequest:
    return gateway_call("gateway.update_bridge_url", "PATCH", BRIDGE_URL_PATH, json={"url": url})
