{"content": "import uuid

from django.conf import settings
from django.shortcuts import get_object_or_404
from django.utils import timezone
from pydantic import BaseModel, Field
from rest_framework.decorators import action
from rest_framework.exceptions import PermissionDenied, ValidationError
from rest_framework.response import Response
from rest_framework.viewsets import GenericViewSet

from care.abdm.api.errors import abdm_exception_handler
from care.abdm.models import AbdmFacility
from care.abdm.service.bridge import expected_bridge_url, list_bridge_services
from care.abdm.service.callbacks import get_jwks
from care.facility.models import Facility
from care.security.authorization import AuthorizationController


class FacilityConfigRequest(BaseModel):
    hfr_id: str = Field(default="", max_length=64)
    hip_id: str = Field(default="", max_length=64)
    hiu_id: str = Field(default="", max_length=64)
    is_hip: bool = False
    is_hiu: bool = False
    display_name: str = Field(default="", max_length=255)


def serialize_config(facility: Facility, config: AbdmFacility | None) -> dict:
    return {
        "id": str(config.external_id) if config else None,
        "facility": str(facility.external_id),
        "hfr_id": config.hfr_id if config else "",
        "hip_id": config.hip_id if config else "",
        "hiu_id": config.hiu_id if config else "",
        "is_hip": config.is_hip if config else False,
        "is_hiu": config.is_hiu if config else False,
        "display_name": config.display_name if config else "",
        "last_synced_at": config.last_synced_at if config else None,
    }


def suggest_service(services: list, facility: Facility, config: AbdmFacility | None):
    """The bridge service that most likely is this facility, or None."""
    hfr_id = (config.hfr_id if config else "").strip()
    name = facility.name.casefold()
    for service in services:
        service_id = str(service.get("id") or "")
        if hfr_id and (service_id == hfr_id or service_id.startswith(f"{hfr_id}_")):
            return service, "hfr_id"
    for service in services:
        # The gateway truncates service names to 15 characters.
        service_name = str(service.get("name") or "").casefold()
        if service_name and name.startswith(service_name):
            return service, "name"
    return None, None


def _gateway_failure(row) -> Response:
    return Response(
        {
            "errors": [
                {
                    "type": "abdm_error",
                    "code": row.error_code or None,
                    "msg": row.error_message or f"ABDM returned HTTP {row.http_status}",
                    "request_id": row.request_id,
                }
            ]
        },
        status=502,
    )


class AbdmFacilityViewSet(GenericViewSet):
    """A facility's ABDM identity: its HIP and HIU service ids on the bridge."""

    lookup_field = "facility"

    def get_exception_handler(self):
        return abdm_exception_handler

    def _facility(self, facility_id) -> Facility:
        if not facility_id:
            raise ValidationError({"facility": "This parameter is required"})
        try:
            uuid.UUID(str(facility_id))
        except ValueError as e:
            raise ValidationError({"facility": "Not a valid id"}) from e
        return get_object_or_404(Facility, external_id=facility_id, deleted=False)

    def _writable_facility(self, facility_id) -> Facility:
        facility = self._facility(facility_id)
        if not AuthorizationController.call(
            "can_update_facility_obj", self.request.user, facility
        ):
            raise PermissionDenied("You do not have permission to update this facility")
        return facility

    @staticmethod
    def _config(facility) -> AbdmFacility | None:
        return AbdmFacility.objects.filter(facility=facility, deleted=False).first()

    def list(self, request):
        facility = self._facility(request.query_params.get("facility"))
        return Response(serialize_config(facility, self._config(facility)))

    def retrieve(self, request, facility=None):
        facility = self._facility(facility)
        return Response(serialize_config(facility, self._config(facility)))

    def update(self, request, facility=None):
        facility = self._writable_facility(facility)
        data = FacilityConfigRequest.model_validate(request.data)
        config = self._config(facility) or AbdmFacility(
            facility=facility, created_by=request.user
        )
        for key, value in data.model_dump().items():
            setattr(config, key, value.strip() if isinstance(value, str) else value)
        config.updated_by = request.user
        config.save()
        return Response(serialize_config(facility, config))

    @action(detail=False, methods=["post"])
    def sync(self, request):
        facility = self._writable_facility(
            request.data.get("facility") or request.query_params.get("facility")
        )
        config = self._config(facility)
        row = list_bridge_services()
        if not row.ok:
            return _gateway_failure(row)
        body = row.response_body if isinstance(row.response_body, dict) else {}
        services = body.get("services") or []
        service, matched_by = suggest_service(services, facility, config)
        types = set(service.get("types") or []) if service else set()
        if config:
            config.last_synced_at = timezone.now()
            config.save(update_fields=["last_synced_at"])
        return Response(
            {
                "bridge": body.get("bridge"),
                "services": services,
                "suggestion": {
                    "hip_id": service["id"] if "HIP" in types else "",
                    "hiu_id": service["id"] if "HIU" in types else "",
                    "is_hip": "HIP" in types,
                    "is_hiu": "HIU" in types,
                    "display_name": service.get("name", ""),
                    "matched_by": matched_by,
                }
                if service
                else None,
                "current": serialize_config(facility, config),
            }
        )

    @action(detail=False, methods=["get"])
    def bridge(self, request):
        facility = self._writable_facility(request.query_params.get("facility"))
        config = self._config(facility)
        expected = expected_bridge_url()
        row = list_bridge_services()
        body = row.response_body if row.ok and isinstance(row.response_body, dict) else {}
        bridge = body.get("bridge") or {}
        services = body.get("services") or []
        registered = bridge.get("url")
        active = {
            kind: {s.get("id") for s in services if s.get("active") and kind in (s.get("types") or [])}
            for kind in ("HIP", "HIU")
        }
        try:
            jwks_ok, jwks_detail = bool(get_jwks().get("keys")), ""
        except Exception as e:  # noqa: BLE001
            jwks_ok, jwks_detail = False, type(e).__name__

        def check(name, ok, detail=""):
            return {"check": name, "ok": bool(ok), "detail": detail}

        readiness = [
            check("abdm_enabled", settings.ABDM_ENABLED),
            check("callback_base_url", expected, expected or "ABDM_CALLBACK_BASE_URL is not set"),
            check("gateway_session", row.ok, row.error_message),
            check(
                "bridge_url_matches",
                registered and expected and registered.rstrip("/") == expected.rstrip("/"),
                f"registered {registered or 'unknown'}, expected {expected or 'unset'}",
            ),
            check(
                "bridge_active",
                bridge.get("active") and not bridge.get("blocklisted"),
                bridge.get("id", ""),
            ),
            check("callback_keys", jwks_ok, jwks_detail),
            check("facility_configured", config and (config.is_hip or config.is_hiu)),
        ]
        if config and config.is_hip:
            readiness.append(check("hip_service", config.hip_id in active["HIP"], config.hip_id))
        if config and config.is_hiu:
            readiness.append(check("hiu_service", config.hiu_id in active["HIU"], config.hiu_id))
        return Response(
            {
                "expected_bridge_url": expected,
                "registered_bridge_url": registered,
                "bridge": bridge or None,
                "services": services,
                "readiness": readiness,
                "config": serialize_config(facility, config),
            }
        )
