import logging
import re
from datetime import UTC, datetime

from django.utils import timezone
from django.utils.dateparse import parse_datetime

from care.abdm.models import AbdmCallback, AbdmFacility, AbhaNumber
from care.abdm.service.gateway_calls import gateway_call

logger = logging.getLogger(__name__)

HI_TYPES = ("OPConsultation", "Prescription", "DiagnosticReport", "DischargeSummary")
# Today's link page names this `hiTypes`; the sandbox accepted the singular
# `hiType` as a string (sbx E11). Verify against the live gateway.
HI_TYPE_KEY = "hiType"

ENCOUNTER_CLASS_LABELS = {
    "imp": "Inpatient",
    "amb": "OPD",
    "obsenc": "Observation",
    "emer": "Emergency",
    "vr": "Teleconsultation",
    "hh": "Home health",
}
CARE_GENDERS = {"male": "M", "female": "F"}
ABDM_GENDERS = {"M", "F", "O", "D", "T", "U"}


class HipError(Exception):
    def __init__(self, code: str, message: str):
        super().__init__(message)
        self.code = code
        self.message = message


def iso(value: datetime | None = None) -> str:
    value = value or timezone.now()
    return (
        value.astimezone(UTC).isoformat(timespec="milliseconds").replace("+00:00", "Z")
    )


def parse_iso(value) -> datetime | None:
    if not value:
        return None
    try:
        parsed = parse_datetime(str(value))
    except ValueError:
        return None
    if parsed and timezone.is_naive(parsed):
        parsed = timezone.make_aware(parsed, UTC)
    return parsed


def digits(value: str) -> str:
    return re.sub(r"\D", "", value or "")


def abha_number_value(abha: AbhaNumber) -> int | None:
    value = digits(abha.abha_number)
    return int(value) if value else None


def gender_code(abha: AbhaNumber) -> str:
    if abha.gender in ABDM_GENDERS:
        return abha.gender
    patient_gender = (abha.patient.gender if abha.patient else "") or ""
    return CARE_GENDERS.get(patient_gender.lower(), "O")


def year_of_birth(abha: AbhaNumber) -> int | None:
    patient = abha.patient
    if abha.year_of_birth:
        return abha.year_of_birth
    if abha.date_of_birth:
        return abha.date_of_birth.year
    if patient and patient.year_of_birth:
        return patient.year_of_birth
    if patient and patient.date_of_birth:
        return patient.date_of_birth.year
    return None


def patient_reference(patient) -> str:
    return str(patient.external_id)


def encounter_start(encounter) -> datetime:
    return parse_iso((encounter.period or {}).get("start")) or encounter.created_date


def encounter_end(encounter) -> datetime:
    return parse_iso((encounter.period or {}).get("end")) or encounter_start(encounter)


def care_context_display(encounter) -> str:
    label = ENCOUNTER_CLASS_LABELS.get(encounter.encounter_class or "", "Hospital")
    start = timezone.localtime(encounter_start(encounter))
    return f"{label} visit, {start:%d %b %Y}"


def patient_blocks(patient, contexts: list[dict]) -> list[dict]:
    """One `patient` block per HI type (sbx E11/F7).

    `contexts` items: {"referenceNumber", "display", "hiTypes": [...]}.
    """
    blocks = []
    for hi_type in HI_TYPES:
        care_contexts = [
            {"referenceNumber": c["referenceNumber"], "display": c["display"]}
            for c in contexts
            if hi_type in c["hiTypes"]
        ]
        if care_contexts:
            blocks.append(
                {
                    "referenceNumber": patient_reference(patient),
                    "display": patient.name,
                    "careContexts": care_contexts,
                    HI_TYPE_KEY: hi_type,
                    "count": len(care_contexts),
                }
            )
    return blocks


def context_entry(care_context) -> dict:
    return {
        "referenceNumber": care_context.reference_number,
        "display": care_context.display,
        "hiTypes": list(care_context.hi_types or []),
    }


def header(callback: AbdmCallback, name: str) -> str:
    name = name.lower()
    for key, value in (callback.headers or {}).items():
        if key.lower() == name:
            return str(value)
    return ""


def facility_for_hip_id(hip_id: str) -> AbdmFacility | None:
    if not hip_id:
        return None
    return (
        AbdmFacility.objects.filter(hip_id=hip_id, deleted=False)
        .select_related("facility")
        .first()
    )


def callback_facility(callback: AbdmCallback, hip_id: str = "") -> AbdmFacility | None:
    return facility_for_hip_id(hip_id or header(callback, "X-HIP-ID"))


def reply(operation: str, path: str, body: dict, facility=None, patient=None):
    row = gateway_call(
        operation, "POST", path, json=body, facility=facility, patient=patient
    )
    if not row.ok:
        logger.warning(
            "ABDM %s answer refused REQUEST-ID=%s status=%s code=%s",
            operation,
            row.request_id,
            row.http_status,
            row.error_code,
        )
    return row


def error_block(code: str, message: str) -> dict:
    return {"code": code, "message": message}


def outbound_error(row) -> dict:
    return {
        "code": row.error_code or None,
        "message": row.error_message or f"ABDM returned HTTP {row.http_status}",
        "http_status": row.http_status,
        "request_id": row.request_id,
    }
"}

{"content": "import base64
import hashlib
import json
import logging
from datetime import timedelta

from django.conf import settings
from django.utils import timezone

from care.abdm.callbacks.base import CallbackNotReady
from care.abdm.hiu.service import (
    TERMINAL_CONSENT_STATUSES,
    HiuError,
    callback_error,
    gateway_error,
    hiu_headers,
    iso,
)
from care.abdm.models import (
    AbdmCallback,
    AbdmConsentArtefact,
    AbdmFetchedRecord,
    AbdmHealthInfoRequest,
)
from care.abdm.service.dataflow_crypto import (
    DEFAULT_KEY_LIFETIME,
    DataflowCryptoError,
    KeyPair,
    decrypt_at_rest,
    decrypt_from,
    encrypt_at_rest,
    generate_key_material,
)
from care.abdm.service.gateway_calls import complete_outbound, gateway_call

logger = logging.getLogger(__name__)

REQUEST_PATH = "/api/hiecm/data-flow/v3/health-information/request"
NOTIFY_PATH = "/api/hiecm/data-flow/v3/health-information/notify"
# A late page may still arrive just after the key's advertised expiry.
KEY_GRACE = timedelta(minutes=10)
OPEN_STATUSES = ("requested", "acknowledged", "receiving")


def data_push_url() -> str:
    return settings.ABDM_CALLBACK_BASE_URL.rstrip("/") + settings.ABDM_DATA_PUSH_PATH


def request_health_information(
    artefact: AbdmConsentArtefact,
) -> AbdmHealthInfoRequest:
    if artefact.status != "GRANTED":
        raise HiuError("The consent artefact is not granted")
    consent_request = artefact.consent_request
    config = consent_request.facility
    granted = (artefact.detail.get("permission") or {}).get("dateRange") or {}
    # Echo the granted range verbatim: the HIP rejects anything wider.
    date_from = granted.get("from") or (
        iso(artefact.date_from) if artefact.date_from else None
    )
    date_to = granted.get("to") or (iso(artefact.date_to) if artefact.date_to else None)
    expiry = timezone.now() + DEFAULT_KEY_LIFETIME
    pair, key_material = generate_key_material(expiry)
    hi_request = AbdmHealthInfoRequest.objects.create(
        artefact=artefact,
        date_from=artefact.date_from,
        date_to=artefact.date_to,
        private_key=encrypt_at_rest(pair.private_key),
        public_key=pair.public_key_b64,
        nonce=pair.nonce_b64,
        key_expires_at=expiry,
        status="requested",
    )
    row = gateway_call(
        "hiu.health_information_request",
        "POST",
        REQUEST_PATH,
        json={
            "hiRequest": {
                "consent": {"id": artefact.consent_id},
                "dateRange": {"from": date_from, "to": date_to},
                "dataPushUrl": data_push_url(),
                "keyMaterial": key_material,
            }
        },
        headers=hiu_headers(config),
        facility=config,
        patient=consent_request.patient,
    )
    hi_request.request_id = row.request_id
    if not row.ok:
        hi_request.status = "failed"
        hi_request.error = gateway_error(row)
        hi_request.private_key = ""
    hi_request.save(update_fields=["request_id", "status", "error", "private_key"])
    return hi_request


def on_request(callback: AbdmCallback) -> None:
    request_id = callback.response_request_id
    hi_request = AbdmHealthInfoRequest.objects.filter(request_id=request_id).first()
    if hi_request is None:
        raise CallbackNotReady(f"health information request {request_id}")
    complete_outbound(request_id)
    body = callback.body
    data = body.get("hiRequest") or {}
    error = callback_error(body)
    transaction_id = str(data.get("transactionId") or "")
    if error or not transaction_id:
        hi_request.status = "failed"
        hi_request.error = error or {"message": "on-request had no transactionId"}
        hi_request.private_key = ""
    else:
        hi_request.transaction_id = transaction_id[:128]
        if hi_request.status == "requested":
            hi_request.status = "acknowledged"
        hi_request.meta["session_status"] = data.get("sessionStatus")
    hi_request.save(
        update_fields=["transaction_id", "status", "error", "private_key", "meta"]
    )


def _as_int(value, default: int) -> int:
    try:
        return int(value)
    except (TypeError, ValueError):
        return default


def checksum_matches(checksum: str, *candidates: bytes) -> bool:
    """MD5 input bytes and encoding are unpublished (L5): accept hex or base64."""
    checksum = checksum.strip()
    for data in candidates:
        digest = hashlib.md5(data, usedforsecurity=False).digest()
        if checksum.lower() == digest.hex() or checksum == base64.b64encode(
            digest
        ).decode():
            return True
    return False


def _store_entry(hi_request, own: KeyPair, peer: dict, entry, page_number):
    entry = entry if isinstance(entry, dict) else {}
    reference = str(entry.get("careContextReference") or "")
    checksum = str(entry.get("checksum") or "")
    content = entry.get("content")
    error, bundle, checksum_ok = "", None, None
    if not isinstance(content, str) or not content:
        error = "Entry has no inline content"
    else:
        try:
            plaintext = decrypt_from(peer, own, content)
        except DataflowCryptoError as e:
            error = f"Could not decrypt: {e}"
        else:
            if checksum:
                checksum_ok = checksum_matches(checksum, plaintext, content.encode())
            try:
                bundle = json.loads(plaintext)
            except ValueError:
                error = "Decrypted content is not JSON"
            if bundle is not None and not isinstance(bundle, dict):
                bundle, error = None, "Decrypted content is not a FHIR bundle"
    AbdmFetchedRecord.objects.create(
        request=hi_request,
        care_context_reference=reference[:255],
        page_number=page_number,
        media=str(entry.get("media") or "")[:64],
        checksum_ok=checksum_ok,
        bundle=bundle,
        erase_at=hi_request.artefact.data_erase_at,
        meta={"error": error} if error else {},
    )
    return reference, error


def process_data_push(callback: AbdmCallback) -> None:
    body = callback.body
    transaction_id = str(body.get("transactionId") or "")
    hi_request = (
        AbdmHealthInfoRequest.objects.select_related("artefact__consent_request")
        .filter(transaction_id=transaction_id)
        .first()
    )
    if hi_request is None:
        raise CallbackNotReady(f"transaction {transaction_id}")
    page_number = _as_int(body.get("pageNumber"), 1)
    page_count = max(_as_int(body.get("pageCount"), 1), 1)
    pages = hi_request.meta.get("pages") or []
    if page_number in pages:
        return
    if not hi_request.private_key:
        hi_request.meta.setdefault("late_pages", []).append(page_number)
        hi_request.save(update_fields=["meta"])
        return

    own = KeyPair(
        private_key=decrypt_at_rest(hi_request.private_key),
        public_key_b64=hi_request.public_key,
        nonce_b64=hi_request.nonce,
    )
    peer = body.get("keyMaterial") or {}
    outcomes = hi_request.meta.get("outcomes") or {}
    for entry in body.get("entries") or []:
        reference, error = _store_entry(hi_request, own, peer, entry, page_number)
        outcome = outcomes.setdefault(reference, {"ok": 0, "errors": []})
        if error:
            outcome["errors"].append(error)
        else:
            outcome["ok"] += 1

    pages.append(page_number)
    hi_request.meta["pages"] = sorted(pages)
    hi_request.meta["outcomes"] = outcomes
    hi_request.expected_pages = page_count
    hi_request.received_pages = len(pages)
    hi_request.status = "receiving"
    if hi_request.received_pages >= page_count:
        finish_transfer(hi_request)
    hi_request.save()


def finish_transfer(hi_request: AbdmHealthInfoRequest) -> None:
    """Erase the key and tell the gateway how the transfer went. Caller saves."""
    artefact = hi_request.artefact
    consent_request = artefact.consent_request
    config = consent_request.facility
    outcomes = hi_request.meta.get("outcomes") or {}
    responses = [
        {
            "careContextReference": reference,
            "hiStatus": "ERRORED" if outcome["errors"] else "OK",
            "description": "; ".join(dict.fromkeys(outcome["errors"]))
            or "Data received",
        }
        for reference, outcome in outcomes.items()
    ]
    received = any(outcome["ok"] for outcome in outcomes.values())
    session_status = "RECEIVED" if received else "FAILED"
    hi_request.private_key = ""
    hi_request.status = "received" if received else "failed"
    if not received:
        hi_request.error = {"message": "No entry could be decrypted"}
    row = gateway_call(
        "hiu.health_information_notify",
        "POST",
        NOTIFY_PATH,
        json={
            "notification": {
                "consentId": artefact.consent_id,
                "transactionId": hi_request.transaction_id,
                "doneAt": iso(timezone.now()),
                "notifier": {"type": "HIU", "id": config.hiu_id},
                "statusNotification": {
                    "sessionStatus": session_status,
                    "hipId": artefact.hip_id,
                    "statusResponses": responses,
                },
            }
        },
        facility=config,
        patient=consent_request.patient,
    )
    hi_request.meta["notify"] = {"request_id": row.request_id, "ok": row.ok}


def _erase(records) -> int:
    return records.filter(erased_at__isnull=True).update(
        bundle=None, erased_at=timezone.now()
    )


def erase_artefact(artefact: AbdmConsentArtefact) -> int:
    """Drop everything fetched under an artefact, now: it was revoked or expired."""
    erased = _erase(AbdmFetchedRecord.objects.filter(request__artefact=artefact))
    artefact.health_info_requests.exclude(private_key="").update(private_key="")
    artefact.health_info_requests.filter(status__in=OPEN_STATUSES).update(
        status="failed", error={"message": f"Consent {artefact.status.lower()}"}
    )
    return erased


def erase_expired() -> dict:
    now = timezone.now()
    by_date = _erase(AbdmFetchedRecord.objects.filter(erase_at__lte=now))
    by_consent = _erase(
        AbdmFetchedRecord.objects.filter(
            request__artefact__status__in=TERMINAL_CONSENT_STATUSES
        )
    )
    stale = AbdmHealthInfoRequest.objects.filter(key_expires_at__lt=now - KEY_GRACE)
    expired = stale.filter(status__in=OPEN_STATUSES).update(
        status="failed",
        private_key="",
        error={"message": "No data arrived before the key expired"},
    )
    stale.exclude(private_key="").update(private_key="")
    return {"by_date": by_date, "by_consent": by_consent, "expired_requests": expired}
