import logging
from datetime import timedelta

import jwt
from django.conf import settings
from django.db import transaction
from django.utils import timezone

from care.abdm.callbacks.base import CallbackNotReady
from care.abdm.hip.service import (
    HI_TYPES,
    HipError,
    abha_number_value,
    care_context_display,
    context_entry,
    gender_code,
    iso,
    outbound_error,
    patient_blocks,
    patient_reference,
    year_of_birth,
)
from care.abdm.models import (
    AbdmCallback,
    AbdmCareContext,
    AbdmFacility,
    AbdmLinkToken,
    AbhaNumber,
)
from care.abdm.service.dataflow_crypto import (
    DataflowCryptoError,
    decrypt_at_rest,
    encrypt_at_rest,
)
from care.abdm.service.gateway_calls import complete_outbound, gateway_call

logger = logging.getLogger(__name__)

GENERATE_TOKEN_PATH = "/api/hiecm/v3/token/generate-token"
LINK_PATH = "/api/hiecm/hip/v3/link/carecontext"
NOTIFY_PATH = "/api/hiecm/hip/v3/link/context/notify"
BLOCKED_CODE = "ABDM-1027"
BLOCKED_FOR = timedelta(hours=24)
# The token is valid for six months; refresh shortly before it lapses.
TOKEN_FALLBACK_LIFETIME = timedelta(days=180)
TOKEN_MIN_REMAINING = timedelta(minutes=5)
# Notify too soon after linking and ABDM has not indexed the link (sbx F9).
NOTIFY_DELAY_SECONDS = 60
NOTIFY_MAX_ATTEMPTS = 2

PENDING = "pending"
LINKING = "linking"
LINKED = "linked"
FAILED = "failed"


def _code(error) -> str:
    return str((error or {}).get("code") or "").split(":")[0].strip()


def link_encounter(encounter, user, hi_types=None) -> AbdmCareContext:
    """Create or refresh the care context for an encounter and schedule linking.

    Raises HipError before writing anything when the encounter cannot be linked.
    """
    config = (
        AbdmFacility.objects.filter(facility=encounter.facility, deleted=False)
        .exclude(hip_id="")
        .first()
    )
    if config is None:
        raise HipError(
            "facility_not_configured",
            "This facility has no ABDM HIP id. Configure it in the facility's ABDM settings.",
        )
    abha = AbhaNumber.objects.filter(patient=encounter.patient, deleted=False).first()
    if abha is None:
        raise HipError("patient_has_no_abha", "This patient has no linked ABHA.")
    if hi_types:
        unknown = sorted(set(hi_types) - set(HI_TYPES))
        if unknown:
            raise HipError("invalid_hi_types", f"Unknown HI types: {', '.join(unknown)}")
    else:
        from care.abdm.fhir import available_hi_types

        hi_types = available_hi_types(encounter)
    hi_types = [t for t in HI_TYPES if t in set(hi_types or [])]
    if not hi_types:
        raise HipError(
            "no_hi_types", "This encounter has no records that ABDM can share yet."
        )

    context = AbdmCareContext.objects.filter(
        encounter=encounter, facility=config, deleted=False
    ).first() or AbdmCareContext(
        encounter=encounter,
        facility=config,
        reference_number=str(encounter.external_id),
        created_by=user,
    )
    context.abha_number = abha
    context.display = care_context_display(encounter)
    context.hi_types = hi_types
    context.status = PENDING
    context.error = None
    context.updated_by = user
    context.save()
    schedule_linking(abha, config)
    return context


def schedule_linking(abha: AbhaNumber, config: AbdmFacility) -> None:
    from care.abdm.hip.tasks import link_pending_care_contexts

    transaction.on_commit(
        lambda: link_pending_care_contexts.delay(abha.id, config.id)
    )


def schedule_notify(context: AbdmCareContext, attempt: int = 0) -> None:
    from care.abdm.hip.tasks import notify_care_context

    transaction.on_commit(
        lambda: notify_care_context.apply_async(
            (context.id, attempt), countdown=NOTIFY_DELAY_SECONDS
        )
    )


def pending_contexts(abha: AbhaNumber, config: AbdmFacility):
    return list(
        AbdmCareContext.objects.select_for_update()
        .filter(abha_number=abha, facility=config, status=PENDING, deleted=False)
        .select_related("encounter")
        .order_by("id")
    )


def link_token_value(token: AbdmLinkToken) -> str:
    if not token.token:
        return ""
    try:
        return decrypt_at_rest(token.token).decode()
    except DataflowCryptoError:
        return ""


def token_usable(token: AbdmLinkToken | None) -> bool:
    return bool(
        token
        and token.status == "active"
        and link_token_value(token)
        and (
            token.expires_at is None
            or token.expires_at > timezone.now() + TOKEN_MIN_REMAINING
        )
    )


def _blocked(token: AbdmLinkToken) -> bool:
    return (
        token.status == FAILED
        and _code(token.error) == BLOCKED_CODE
        and token.requested_at is not None
        and timezone.now() - token.requested_at < BLOCKED_FOR
    )


def _within_window(token: AbdmLinkToken) -> bool:
    window = timedelta(seconds=settings.ABDM_LINK_TOKEN_REQUEST_WINDOW_SECONDS)
    return (
        token.requested_at is not None and timezone.now() - token.requested_at < window
    )


def ensure_link_token(abha: AbhaNumber, config: AbdmFacility) -> AbdmLinkToken:
    """An active token, or the token row whose request is outstanding or failed."""
    token = (
        AbdmLinkToken.objects.select_for_update()
        .filter(abha_number=abha, facility=config, deleted=False)
        .first()
    )
    if token and (token_usable(token) or _blocked(token) or _within_window(token)):
        return token
    token = token or AbdmLinkToken(abha_number=abha, facility=config)
    patient = abha.patient
    row = gateway_call(
        "hip.generate_token",
        "POST",
        GENERATE_TOKEN_PATH,
        json={
            "abhaNumber": abha_number_value(abha),
            "abhaAddress": abha.abha_address,
            "name": abha.name or (patient.name if patient else ""),
            "gender": gender_code(abha),
            "yearOfBirth": year_of_birth(abha),
        },
        headers={"X-HIP-ID": config.hip_id},
        facility=config,
        patient=patient,
    )
    token.request_id = row.request_id
    token.requested_at = timezone.now()
    token.token = ""
    token.expires_at = None
    token.status = "requested" if row.ok else FAILED
    token.error = None if row.ok else outbound_error(row)
    token.save()
    return token


def process_pending(abha: AbhaNumber, config: AbdmFacility) -> None:
    contexts = pending_contexts(abha, config)
    if not contexts:
        return
    token = ensure_link_token(abha, config)
    if token_usable(token):
        send_link(token, contexts)
    elif token.status == FAILED:
        fail_contexts(contexts, {"stage": "link_token", **(token.error or {})})


def fail_contexts(contexts, error: dict) -> None:
    for context in contexts:
        context.status = FAILED
        context.error = error
        context.save(update_fields=["status", "error", "modified_date"])


def send_link(token: AbdmLinkToken, contexts: list[AbdmCareContext]) -> None:
    abha = token.abha_number
    config = token.facility
    patient = abha.patient
    row = gateway_call(
        "hip.link_carecontext",
        "POST",
        LINK_PATH,
        json={
            "abhaNumber": abha_number_value(abha),
            "abhaAddress": abha.abha_address,
            "patient": patient_blocks(patient, [context_entry(c) for c in contexts]),
        },
        headers={"X-HIP-ID": config.hip_id, "X-LINK-TOKEN": link_token_value(token)},
        facility=config,
        patient=patient,
    )
    for context in contexts:
        context.last_request_id = row.request_id
        context.status = LINKING if row.ok else FAILED
        context.error = None if row.ok else {"stage": "link", **outbound_error(row)}
        context.save(
            update_fields=["last_request_id", "status", "error", "modified_date"]
        )


def _token_expiry(link_token: str):
    try:
        exp = jwt.decode(link_token, options={"verify_signature": False}).get("exp")
    except jwt.PyJWTError:
        exp = None
    if exp:
        return timezone.datetime.fromtimestamp(int(exp), tz=timezone.UTC)
    return timezone.now() + TOKEN_FALLBACK_LIFETIME


def on_generate_token(callback: AbdmCallback) -> None:
    request_id = callback.response_request_id
    token = (
        AbdmLinkToken.objects.select_for_update()
        .filter(request_id=request_id, deleted=False)
        .select_related("abha_number__patient", "facility")
        .first()
        if request_id
        else None
    )
    if token is None:
        if request_id:
            raise CallbackNotReady(f"no link token request {request_id}")
        return
    complete_outbound(request_id)
    body = callback.body
    link_token = body.get("linkToken")
    contexts = pending_contexts(token.abha_number, token.facility)
    if body.get("error") or not link_token:
        token.status = FAILED
        token.error = body.get("error") or {"message": "No linkToken in the callback"}
        token.save(update_fields=["status", "error", "modified_date"])
        fail_contexts(contexts, {"stage": "link_token", **token.error})
        return
    token.token = encrypt_at_rest(str(link_token).encode())
    token.expires_at = _token_expiry(str(link_token))
    token.status = "active"
    token.error = None
    token.save(update_fields=["token", "expires_at", "status", "error", "modified_date"])
    if contexts:
        send_link(token, contexts)


def on_carecontext(callback: AbdmCallback) -> None:
    request_id = callback.response_request_id
    if not request_id:
        return
    contexts = list(
        AbdmCareContext.objects.select_for_update().filter(
            last_request_id=request_id, deleted=False
        )
    )
    if not contexts:
        raise CallbackNotReady(f"no care context for link request {request_id}")
    complete_outbound(request_id)
    error = callback.body.get("error")
    for context in contexts:
        context.meta = {**context.meta, "link_status": callback.body.get("status")}
        if error:
            context.status = FAILED
            context.error = {"stage": "link", **error}
            if _code(error) == "ABDM-1026":
                AbdmLinkToken.objects.filter(
                    abha_number_id=context.abha_number_id,
                    facility_id=context.facility_id,
                    deleted=False,
                ).update(status=FAILED, error=error)
        else:
            context.status = LINKED
            context.linked_at = timezone.now()
            context.error = None
            context.meta.pop("notify_attempts", None)
        context.save()
        if context.status == LINKED:
            schedule_notify(context)


def notify(context: AbdmCareContext, attempt: int = 0) -> None:
    if context.status != LINKED:
        return
    abha = context.abha_number
    config = context.facility
    row = gateway_call(
        "hip.link_context_notify",
        "POST",
        NOTIFY_PATH,
        json={
            "notification": {
                "patient": {"id": abha.abha_address},
                "careContext": {
                    "patientReference": patient_reference(context.encounter.patient),
                    "careContextReference": context.reference_number,
                },
                "hiTypes": list(context.hi_types or []),
                "date": iso(),
                "hip": {"id": config.hip_id},
            }
        },
        headers={"X-HIP-ID": config.hip_id},
        facility=config,
        patient=abha.patient,
    )
    context.meta = {
        **context.meta,
        "notify_request_id": row.request_id,
        "notify_attempts": attempt + 1,
    }
    if row.ok:
        context.error = None
    else:
        context.error = {"stage": "notify", **outbound_error(row)}
        _maybe_retry_notify(context, row.error_message, attempt)
    context.save(update_fields=["meta", "error", "modified_date"])


def _maybe_retry_notify(context, message: str, attempt: int) -> None:
    if "no link" in (message or "").lower() and attempt + 1 < NOTIFY_MAX_ATTEMPTS:
        schedule_notify(context, attempt + 1)


def on_context_notify(callback: AbdmCallback) -> None:
    request_id = callback.response_request_id
    if not request_id:
        return
    context = (
        AbdmCareContext.objects.select_for_update()
        .filter(meta__notify_request_id=request_id, deleted=False)
        .first()
    )
    if context is None:
        raise CallbackNotReady(f"no care context for notify request {request_id}")
    complete_outbound(request_id)
    body = callback.body
    error = body.get("error")
    ack = (body.get("acknowledgement") or {}).get("status")
    context.meta = {**context.meta, "notify_status": ack}
    if error:
        context.error = {"stage": "notify", **error}
        _maybe_retry_notify(
            context,
            str(error.get("message") or ""),
            int(context.meta.get("notify_attempts", 1)) - 1,
        )
    else:
        context.notified_at = timezone.now()
        context.error = None
    context.save(update_fields=["meta", "error", "notified_at", "modified_date"])


def on_sms_notify(callback: AbdmCallback) -> None:
    complete_outbound(callback.response_request_id)


def retry(context: AbdmCareContext) -> AbdmCareContext:
    if context.status == LINKED:
        if not context.notified_at:
            context.meta.pop("notify_attempts", None)
            context.save(update_fields=["meta", "modified_date"])
            schedule_notify(context)
        return context
    if context.status == LINKING:
        return context
    context.status = PENDING
    context.error = None
    context.save(update_fields=["status", "error", "modified_date"])
    schedule_linking(context.abha_number, context.facility)
    return context
