)
from care.emr.models import Patient
from care.facility.models import Facility
from care.security.authorization import AuthorizationController


class ConsentRequestCreate(BaseModel):
    patient: str
    facility: str
    purpose: str = "CAREMGT"
    hi_types: list[str] = Field(min_length=1)
    date_from: datetime
    date_to: datetime
    data_erase_at: datetime
    hip_id: str | None = Field(default=None, max_length=64)


def serialize_transfer(hi_request: AbdmHealthInfoRequest | None) -> dict | None:
    if hi_request is None:
        return None
    return {
        "id": str(hi_request.external_id),
        "status": hi_request.status,
        "transaction_id": hi_request.transaction_id,
        "expected_pages": hi_request.expected_pages,
        "received_pages": hi_request.received_pages,
        "error": hi_request.error,
        "created_date": hi_request.created_date,
        "modified_date": hi_request.modified_date,
    }


def serialize_artefact(artefact: AbdmConsentArtefact) -> dict:
    requests = sorted(
        artefact.health_info_requests.all(), key=lambda r: r.created_date, reverse=True
    )
    return {
        "id": str(artefact.external_id),
        "consent_id": artefact.consent_id,
        "status": artefact.status,
        "hip_id": artefact.hip_id,
        "hip_name": artefact.hip_name,
        "hi_types": artefact.hi_types,
        "care_contexts": artefact.care_contexts,
        "date_from": artefact.date_from,
        "date_to": artefact.date_to,
        "data_erase_at": artefact.data_erase_at,
        "fetch_error": artefact.meta.get("fetch_error"),
        "transfer": serialize_transfer(requests[0] if requests else None),
        "record_count": sum(r.live_records for r in requests),
    }


def serialize_consent_request(obj: AbdmConsentRequest) -> dict:
    requester = obj.requester
    return {
        "id": str(obj.external_id),
        "patient": str(obj.patient.external_id),
        "facility": str(obj.facility.facility.external_id),
        "abha_address": obj.meta.get("abha_address") or obj.abha_number.abha_address,
        "consent_request_id": obj.consent_request_id,
        "purpose": obj.purpose,
        "hi_types": obj.hi_types,
        "hip_id": obj.meta.get("hip_id"),
        "date_from": obj.date_from,
        "date_to": obj.date_to,
        "data_erase_at": obj.data_erase_at,
        "status": obj.status,
        "reason": obj.meta.get("reason"),
        "error": obj.error,
        "requester": {
            "id": str(requester.external_id),
            "username": requester.username,
