def summarize_bundle(bundle: dict | None) -> dict | None:
    if not isinstance(bundle, dict):
        return None
    resources = [
        entry.get("resource") or {}
        for entry in bundle.get("entry") or []
        if isinstance(entry, dict)
    ]
    counts: dict[str, int] = {}
    for resource in resources:
        kind = resource.get("resourceType")
        if kind:
            counts[kind] = counts.get(kind, 0) + 1
    composition = next(
        (r for r in resources if r.get("resourceType") == "Composition"), {}
    )
    kind = composition.get("type") or {}
    codings = kind.get("coding") or [{}]
    return {
        "title": composition.get("title"),
        "date": composition.get("date") or bundle.get("timestamp"),
        "type": kind.get("text") or codings[0].get("display"),
        "type_code": codings[0].get("code"),
        "status": composition.get("status"),
        "resource_types": counts,
    }


