        "page_number": record.page_number,
        "media": record.media,
        "checksum_ok": record.checksum_ok,
        "error": record.meta.get("error"),
        "received_at": record.created_date,
        "erase_at": record.erase_at,
        "summary": summarize_bundle(record.bundle),
        "bundle": record.bundle,
    }


def _gateway_failure(row, consent_request: AbdmConsentRequest) -> Response:
    error = gateway_error(row)
    return Response(
        {
            "errors": [
                {
                    "type": "abdm_error",
                    "code": error["code"],
                    "msg": error["message"],
                    "request_id": row.request_id,
                }
            ],
            "consent_request": serialize_consent_request(consent_request),
        },
        status=502,
    )


class ConsentRequestViewSet(GenericViewSet):
    """Consent requests Care raised as a HIU, and the records they fetched."""

    lookup_field = "external_id"

    def get_exception_handler(self):
        return abdm_exception_handler

    def initial(self, request, *args, **kwargs):
        super().initial(request, *args, **kwargs)
        if not settings.ABDM_ENABLED:
            raise NotFound("ABDM is not enabled on this deployment")

    def _authorize(self, patient):
        if not AuthorizationController.call(
            "can_view_clinical_data", self.request.user, patient
        ):
            raise PermissionDenied("You do not have access to this patient's records")

    def _queryset(self):
        live = Count(
            "records",
            filter=Q(records__erased_at__isnull=True, records__bundle__isnull=False),
        )
        return (
            AbdmConsentRequest.objects.filter(deleted=False)
            .select_related(
                "patient", "facility__facility", "abha_number", "requester"
            )
            .prefetch_related(
                "artefacts",
                Prefetch_health_info_requests(live),
            )
            .order_by("-created_date")
        )

    def _object(self, external_id) -> AbdmConsentRequest:
        obj = get_object_or_404(self._queryset(), external_id=external_id)
        self._authorize(obj.patient)
        return obj

    def list(self, request):
        patient_id = request.query_params.get("patient")
        if not patient_id:
            raise ValidationError({"patient": "This parameter is required"})
        patient = get_object_or_404(Patient, external_id=patient_id, deleted=False)
        self._authorize(patient)
        results = [
            serialize_consent_request(obj)
            for obj in self._queryset().filter(patient=patient)
        ]
        return Response({"count": len(results), "results": results})

    def retrieve(self, request, external_id=None):
        return Response(serialize_consent_request(self._object(external_id)))

    def create(self, request):
        data = ConsentRequestCreate.model_validate(request.data)
        patient = get_object_or_404(Patient, external_id=data.patient, deleted=False)
        self._authorize(patient)
        facility = get_object_or_404(Facility, external_id=data.facility, deleted=False)
        try:
            consent_request, row = create_consent_request(
                patient,
                facility,
                request.user,
                purpose=data.purpose,
                hi_types=data.hi_types,
                date_from=data.date_from,
                date_to=data.date_to,
                data_erase_at=data.data_erase_at,
                hip_id=data.hip_id,
            )
        except HiuError as e:
            raise ValidationError({e.field or "non_field_errors": e.message}) from e
        consent_request = self._queryset().get(id=consent_request.id)
        if not row.ok:
            return _gateway_failure(row, consent_request)
        return Response(serialize_consent_request(consent_request), status=201)

    @action(detail=True, methods=["post"])
    def refresh(self, request, external_id=None):
        consent_request = self._object(external_id)
        try:
            row = refresh_status(consent_request)
        except HiuError as e:
            raise ValidationError({"non_field_errors": e.message}) from e
        if not row.ok:
            return _gateway_failure(row, consent_request)
        return Response(serialize_consent_request(consent_request))

    @action(detail=True, methods=["get"])
    def records(self, request, external_id=None):
        consent_request = self._object(external_id)
        records = (
            AbdmFetchedRecord.objects.filter(
                request__artefact__consent_request=consent_request,
                erased_at__isnull=True,
                bundle__isnull=False,
            )
            .select_related("request__artefact")
            .order_by("request__artefact_id", "care_context_reference", "page_number")
        )
        artefacts: dict[int, dict] = {}
        for record in records:
            artefact = record.request.artefact
            group = artefacts.setdefault(
                artefact.id,
                {
                    "id": str(artefact.external_id),
                    "consent_id": artefact.consent_id,
                    "status": artefact.status,
                    "hip_id": artefact.hip_id,
                    "hip_name": artefact.hip_name,
                    "data_erase_at": artefact.data_erase_at,
                    "care_contexts": {},
                },
            )
            group["care_contexts"].setdefault(record.care_context_reference, []).append(
