{"content": """"User-initiated linking: discovery, link init (OTP) and link confirm."""

import logging
import secrets
import uuid
from datetime import timedelta

from django.conf import settings
from django.contrib.auth.hashers import check_password, make_password
from django.db.models import Q
from django.utils import timezone

from care.abdm.hip.linking import LINKED
from care.abdm.hip.service import (
    callback_facility,
    care_context_display,
    digits,
    error_block,
    iso,
    patient_blocks,
    reply,
)
from care.abdm.models import AbdmCallback, AbdmCareContext, AbdmLinkSession, AbhaNumber
from care.emr.models import Encounter

logger = logging.getLogger(__name__)

ON_DISCOVER_PATH = (
    "/api/hiecm/user-initiated-linking/v3/patient/care-context/on-discover"
)
ON_INIT_PATH = "/api/hiecm/user-initiated-linking/v3/link/care-context/on-init"
ON_CONFIRM_PATH = "/api/hiecm/user-initiated-linking/v3/link/care-context/on-confirm"

OTP_LENGTH = 6
DEV_OTP = "123456"
OTP_VALIDITY = timedelta(minutes=10)
OTP_MAX_ATTEMPTS = 3
MAX_DISCOVERED = 50
ABHA_NUMBER_TYPES = {"ABHA_NUMBER", "HEALTH_NUMBER", "NDHM_HEALTH_NUMBER"}
ABHA_ADDRESS_TYPES = {"ABHA_ADDRESS", "HEALTH_ID", "PHR_ADDRESS"}

PATIENT_NOT_FOUND = "ABDM-1012"
INVALID_CARE_CONTEXTS = "ABDM-1057"
INVALID_LINK_REFERENCE = "ABDM-1056"
OTP_MISMATCH = "ABDM-1036"
SERVICE_UNAVAILABLE = "ABDM-1004"


def _address_variants(address: str) -> set[str]:
    address = (address or "").strip().lower()
    if not address:
        return set()
    local = address.split("@")[0]
    return {address, local, f"{local}@{settings.ABDM_CM_ID.lower()}"}


def match_abha(abha_addresses=(), abha_numbers=()) -> tuple[AbhaNumber | None, str]:
    """Match only on verified ABHA identifiers, never on demographics."""
    numbers = {digits(n) for n in abha_numbers if digits(n)}
    for number in numbers:
        for abha in AbhaNumber.objects.filter(
            deleted=False, patient__isnull=False, patient__deleted=False
        ).filter(abha_number__endswith=number[-4:]):
            if digits(abha.abha_number) == number:
                return abha, "ABHA_NUMBER"
    variants = set().union(*(_address_variants(a) for a in abha_addresses))
    if variants:
        query = Q()
        for variant in variants:
            query |= Q(abha_address__iexact=variant)
        abha = (
            AbhaNumber.objects.filter(
                query, deleted=False, patient__isnull=False, patient__deleted=False
            )
            .select_related("patient")
            .first()
        )
        if abha:
            return abha, "ABHA_ADDRESS"
    return None, ""


def _identifiers(patient: dict) -> tuple[list[str], list[str]]:
    addresses = [patient.get("id")] if patient.get("id") else []
    numbers = []
    for identifier in patient.get("verifiedIdentifiers") or []:
        kind = str(identifier.get("type") or "").upper()
        value = str(identifier.get("value") or "")
        if kind in ABHA_NUMBER_TYPES:
            numbers.append(value)
        elif kind in ABHA_ADDRESS_TYPES:
            addresses.append(value)
    return addresses, numbers


def linkable_contexts(abha: AbhaNumber, config) -> list[dict]:
    """Encounters at this facility not yet linked, with the HI types they hold."""
    from care.abdm.fhir import available_hi_types

    linked = set(
        AbdmCareContext.objects.filter(
            abha_number=abha, facility=config, status=LINKED, deleted=False
        ).values_list("encounter_id", flat=True)
    )
    encounters = (
        Encounter.objects.filter(
            patient=abha.patient, facility=config.facility, deleted=False
        )
        .exclude(id__in=linked)
        .order_by("-created_date")[:MAX_DISCOVERED]
    )
    contexts = []
    for encounter in encounters:
        hi_types = available_hi_types(encounter)
        if hi_types:
            contexts.append(
                {
                    "referenceNumber": str(encounter.external_id),
                    "display": care_context_display(encounter),
                    "hiTypes": list(hi_types),
                }
            )
    return contexts


def on_discover(callback: AbdmCallback) -> None:
    body = callback.body
    transaction_id = str(body.get("transactionId") or "")
    patient = body.get("patient") if isinstance(body.get("patient"), dict) else {}
    config = callback_facility(callback, str(body.get("hipId") or ""))
    addresses, numbers = _identifiers(patient)
    abha, matched_by = match_abha(addresses, numbers)
    contexts = linkable_contexts(abha, config) if abha and config else []

    if transaction_id:
        AbdmLinkSession.objects.update_or_create(
            transaction_id=transaction_id,
            defaults={
                "facility": config,
                "abha_number": abha,
                "abha_address": (patient.get("id") or "")[:255],
                "care_contexts": contexts,
                "status": "discovered" if contexts else "not_found",
            },
        )
    answer = {
        "transactionId": transaction_id,
        "patient": patient_blocks(abha.patient, contexts) if contexts else [],
        "matchedBy": [matched_by] if contexts else [],
        "response": {"requestId": callback.request_id},
    }
    reply(
        "hip.on_discover",
        ON_DISCOVER_PATH,
        answer,
        facility=config,
        patient=abha.patient if abha else None,
    )


def _requested_references(body: dict) -> list[str]:
    blocks = body.get("patient")
    if isinstance(blocks, dict):
        blocks = [blocks]
    references = []
    for block in blocks or []:
        for context in block.get("careContexts") or []:
            reference = str(context.get("referenceNumber") or "")
            if reference and reference not in references:
                references.append(reference)
    return references


def _init_abha_address(body: dict) -> str:
    patient = body.get("patient")
    if isinstance(patient, dict) and patient.get("id"):
        return str(patient["id"])
    return str(body.get("abhaAddress") or "")


def _masked(mobile: str) -> str:
    value = digits(mobile)
    return f"{'*' * max(len(value) - 4, 0)}{value[-4:]}" if value else ""


def _send_otp(mobile: str, otp: str, facility_name: str) -> bool:
    if not settings.USE_SMS:
        if settings.IS_PRODUCTION:
            return False
        logger.info("ABDM link OTP not sent by SMS: SMS is disabled (dev OTP in use)")
        return True
    from care.utils import sms

    try:
        sms.send_text_message(
            content=(
                f"{otp} is your OTP to link your health records at {facility_name}"
                " with your ABHA. It is valid for 10 minutes."
            ),
            recipients=[mobile],
        )
    except Exception:
        logger.exception("ABDM link OTP could not be sent")
        return False
    return True


def _init_error(callback, transaction_id, config, code, message, patient=None):
    reply(
        "hip.link_on_init",
        ON_INIT_PATH,
        {
            "transactionId": transaction_id,
            "error": error_block(code, message),
            "response": {"requestId": callback.request_id},
        },
        facility=config,
        patient=patient,
    )


def on_link_init(callback: AbdmCallback) -> None:
    body = callback.body
    transaction_id = str(body.get("transactionId") or "")
    session = (
        AbdmLinkSession.objects.select_for_update()
        .filter(transaction_id=transaction_id)
        .first()
        if transaction_id
        else None
    )
    config = callback_facility(callback) or (session.facility if session else None)
    address = _init_abha_address(body) or (session.abha_address if session else "")
    abha = session.abha_number if session and session.abha_number else None
    if abha is None:
        abha, _ = match_abha([address])
    if abha is None or config is None:
        _init_error(
            callback, transaction_id, config, PATIENT_NOT_FOUND, "Patient not found"
        )
        return

    offered = {
        c["referenceNumber"]: c
        for c in (
            session.care_contexts
            if session and session.care_contexts
            else linkable_contexts(abha, config)
        )
    }
    requested = _requested_references(body)
    if not requested or any(r not in offered for r in requested):
        _init_error(
            callback,
            transaction_id,
            config,
            INVALID_CARE_CONTEXTS,
            "Invalid care contexts",
            abha.patient,
        )
        return

    mobile = abha.mobile or abha.patient.phone_number or ""
    otp = (
        "".join(secrets.choice("0123456789") for _ in range(OTP_LENGTH))
        if settings.IS_PRODUCTION
        else DEV_OTP
    )
    if not mobile or not _send_otp(mobile, otp, config.facility.name):
        _init_error(
            callback,
            transaction_id,
            config,
            SERVICE_UNAVAILABLE,
            "Could not send the OTP to the patient's mobile",
            abha.patient,
        )
        return

    expires_at = timezone.now() + OTP_VALIDITY
    session = session or AbdmLinkSession(transaction_id=transaction_id)
    session.facility = config
    session.abha_number = abha
    session.abha_address = address[:255]
    session.care_contexts = [offered[r] for r in requested]
    session.link_reference = str(uuid.uuid4())
    session.otp_hash = make_password(otp)
    session.otp_expires_at = expires_at
    session.status = "otp_sent"
    session.meta = {**session.meta, "otp_attempts": 0}
    session.save()
    reply(
        "hip.link_on_init",
        ON_INIT_PATH,
        {
            "transactionId": transaction_id,
            "link": {
                "referenceNumber": session.link_reference,
                "authenticationType": "DIRECT",
                "meta": {
                    "communicationMedium": "MOBILE",
                    "communicationHint": _masked(mobile),
                    "communicationExpiry": iso(expires_at),
                },
            },
            "response": {"requestId": callback.request_id},
        },
        facility=config,
        patient=abha.patient,
    )


def _confirm_error(callback, config, code, message, patient=None):
    reply(
        "hip.link_on_confirm",
        ON_CONFIRM_PATH,
        {
            "error": error_block(code, message),
            "response": {"requestId": callback.request_id},
        },
        facility=config,
        patient=patient,
    )


def on_link_confirm(callback: AbdmCallback) -> None:
    confirmation = callback.body.get("confirmation") or {}
    reference = str(confirmation.get("linkRefNumber") or "")
    otp = str(confirmation.get("token") or "")
    session = (
        AbdmLinkSession.objects.select_for_update()
        .filter(link_reference=reference, status="otp_sent")
        .select_related("facility__facility", "abha_number__patient")
        .first()
        if reference
        else None
    )
    if session is None or session.abha_number is None or session.facility is None:
        _confirm_error(
            callback,
            callback_facility(callback),
            INVALID_LINK_REFERENCE,
            "Invalid link reference number",
        )
        return
    config = session.facility
    patient = session.abha_number.patient
    if session.otp_expires_at and session.otp_expires_at < timezone.now():
        session.status = "expired"
        session.otp_hash = ""
        session.save(update_fields=["status", "otp_hash", "modified_date"])
        _confirm_error(callback, config, OTP_MISMATCH, "OTP expired", patient)
        return
    if not check_password(otp, session.otp_hash):
        attempts = int(session.meta.get("otp_attempts", 0)) + 1
        session.meta = {**session.meta, "otp_attempts": attempts}
        if attempts >= OTP_MAX_ATTEMPTS:
            session.status = "failed"
            session.otp_hash = ""
        session.save(update_fields=["meta", "status", "otp_hash", "modified_date"])
        _confirm_error(callback, config, OTP_MISMATCH, "Invalid OTP", patient)
        return

    contexts = link_session_contexts(session)
    session.status = "linked"
    session.otp_hash = ""
    session.save(update_fields=["status", "otp_hash", "modified_date"])
    reply(
        "hip.link_on_confirm",
        ON_CONFIRM_PATH,
        {
            "patient": patient_blocks(patient, contexts),
            "response": {"requestId": callback.request_id},
        },
        facility=config,
        patient=patient,
    )


def link_session_contexts(session: AbdmLinkSession) -> list[dict]:
    abha = session.abha_number
    config = session.facility
    encounters = {
        str(e.external_id): e
        for e in Encounter.objects.filter(
            external_id__in=[c["referenceNumber"] for c in session.care_contexts],
            patient=abha.patient,
            facility=config.facility,
            deleted=False,
        )
    }
    linked = []
    now = timezone.now()
    for entry in session.care_contexts:
        encounter = encounters.get(entry["referenceNumber"])
        if encounter is None:
            continue
        context = AbdmCareContext.objects.filter(
            encounter=encounter, facility=config, deleted=False
        ).first() or AbdmCareContext(
            encounter=encounter,
            facility=config,
            reference_number=entry["referenceNumber"],
        )
        context.abha_number = abha
        context.display = entry["display"]
        context.hi_types = entry["hiTypes"]
        context.status = LINKED
        context.linked_at = now
        context.error = None
        context.meta = {**context.meta, "linked_by": "patient"}
        context.save()
        linked.append(entry)
    return linked
