{"content": """"Health information requests: acknowledge, encrypt, push, then notify."""

import hashlib
import json
import logging
from datetime import timedelta

import requests
from django.conf import settings
from django.db import transaction
from django.utils import timezone

from care.abdm.callbacks.base import CallbackNotReady
from care.abdm.hip.linking import LINKED
from care.abdm.hip.service import (
    encounter_end,
    encounter_start,
    error_block,
    iso,
    parse_iso,
    reply,
)
from care.abdm.models import (
    AbdmCallback,
    AbdmCareContext,
    AbdmConsent,
    AbdmDataRequest,
    AbdmDataTransfer,
)
from care.abdm.service.dataflow_crypto import DataflowCryptoError, encrypt_for

logger = logging.getLogger(__name__)

ON_REQUEST_PATH = "/api/hiecm/data-flow/v3/health-information/hip/on-request"
NOTIFY_PATH = "/api/hiecm/data-flow/v3/health-information/notify"
TRANSFER_DEADLINE = timedelta(minutes=20)
# Wait this long for a consent notification that may still be in flight.
CONSENT_GRACE = timedelta(seconds=45)
MEDIA = "application/fhir+json"

CONSENT_EXPIRED = "ABDM-1061"
CONSENT_NOT_GRANTED = "ABDM-1062"
INVALID_DATE_RANGE = "ABDM-1063"
INVALID_REQUEST = "ABDM-1006"


def _validate(consent: AbdmConsent, date_from, date_to, hi_request: dict):
    if consent.status == "EXPIRED" or (
        consent.data_erase_at and consent.data_erase_at < timezone.now()
    ):
        return CONSENT_EXPIRED, "Consent artefact expired"
    if consent.status != "GRANTED" or consent.revoked_at:
        return CONSENT_NOT_GRANTED, "Consent not granted"
    if consent.facility is None:
        return CONSENT_NOT_GRANTED, "Consent is not for a HIP on this server"
    if (
        not date_from
        or not date_to
        or date_from > date_to
        or (consent.date_from and date_from < consent.date_from)
        or (consent.date_to and date_to > consent.date_to)
    ):
        return INVALID_DATE_RANGE, "Date range given is invalid"
    key_material = hi_request.get("keyMaterial") or {}
    if not (
        hi_request.get("dataPushUrl")
        and (key_material.get("dhPublicKey") or {}).get("keyValue")
        and key_material.get("nonce")
    ):
        return INVALID_REQUEST, "dataPushUrl or keyMaterial is missing"
    return None, None


def on_health_information_request(callback: AbdmCallback) -> None:
    body = callback.body
    hi_request = body.get("hiRequest") or {}
    transaction_id = str(
        body.get("transactionId") or hi_request.get("transactionId") or ""
    )
    consent_id = str((hi_request.get("consent") or {}).get("id") or "")
    date_range = hi_request.get("dateRange") or {}
    date_from = parse_iso(date_range.get("from"))
    date_to = parse_iso(date_range.get("to"))

    consent = AbdmConsent.objects.filter(consent_id=consent_id).first()
    if consent is None and timezone.now() - callback.created_date < CONSENT_GRACE:
        raise CallbackNotReady(f"consent {consent_id} not yet known")
    if consent is None:
        code, message = CONSENT_NOT_GRANTED, "Unknown consent"
    else:
        code, message = _validate(consent, date_from, date_to, hi_request)

    data_request = None
    if consent is not None and transaction_id:
        data_request, created = AbdmDataRequest.objects.get_or_create(
            transaction_id=transaction_id,
            defaults={
                "consent": consent,
                "date_from": date_from,
                "date_to": date_to,
                "data_push_url": str(hi_request.get("dataPushUrl") or "")[:1024],
                "key_material": hi_request.get("keyMaterial") or {},
                "status": "failed" if code else "acknowledged",
                "deadline_at": timezone.now() + TRANSFER_DEADLINE,
                "error": error_block(code, message) if code else None,
            },
        )

    answer = {"response": {"requestId": callback.request_id}}
    if code:
        answer["error"] = error_block(code, message)
    else:
        answer["hiRequest"] = {
            "transactionId": transaction_id,
            "sessionStatus": "ACKNOWLEDGED",
        }
    reply(
        "hip.health_information_on_request",
        ON_REQUEST_PATH,
        answer,
        facility=consent.facility if consent else None,
    )
    if data_request is not None and not code and created:
        from care.abdm.hip.tasks import transfer_health_information

        transaction.on_commit(
            lambda: transfer_health_information.delay(data_request.id)
        )


def _in_range(context: AbdmCareContext, date_from, date_to) -> bool:
    start = encounter_start(context.encounter)
    end = encounter_end(context.encounter)
    return (not date_to or start <= date_to) and (not date_from or end >= date_from)


def consented_contexts(data_request: AbdmDataRequest) -> list[AbdmCareContext]:
    consent = data_request.consent
    wanted = {}
    for entry in consent.care_contexts or []:
        reference = str(entry.get("careContextReference") or "")
        if reference:
            wanted[reference] = str(entry.get("patientReference") or "")
    contexts = AbdmCareContext.objects.filter(
        facility=consent.facility,
        reference_number__in=list(wanted),
        status=LINKED,
        deleted=False,
    ).select_related("encounter__patient", "abha_number")
    return [
        c
        for c in contexts
        if wanted[c.reference_number] in ("", str(c.encounter.patient.external_id))
        and _in_range(c, data_request.date_from, data_request.date_to)
    ]


def _push(url: str, payload: dict) -> tuple[bool, dict | None]:
    try:
        response = requests.post(
            url,
            json=payload,
            headers={"Content-Type": "application/json"},
            timeout=settings.ABDM_REQUEST_TIMEOUT,
        )
    except requests.RequestException as e:
        return False, {"message": f"Data push failed: {type(e).__name__}"}
    if 200 <= response.status_code < 300:  # noqa: PLR2004
        return True, None
    return False, {
        "http_status": response.status_code,
        "message": (response.text or "")[:500],
    }


def transfer(data_request: AbdmDataRequest) -> None:
    from care.abdm.fhir import build_bundle

    consent = data_request.consent
    hip_id = consent.facility.hip_id
    data_request.status = "transferring"
    data_request.save(update_fields=["status", "modified_date"])

    pages: list[tuple[AbdmCareContext, str, bytes]] = []
    statuses: dict[str, dict] = {}
    hi_types = set(consent.hi_types or [])
    for context in consented_contexts(data_request):
        for hi_type in context.hi_types or []:
            if hi_type not in hi_types:
                continue
            bundle = build_bundle(context, hi_type)
            if bundle:
                pages.append((context, hi_type, json.dumps(bundle).encode()))
        statuses[context.reference_number] = {
            "careContextReference": context.reference_number,
            "hiStatus": "ERRORED",
            "description": "No data for the consented HI types",
        }

    page_count = len(pages)
    delivered = 0
    for number, (context, hi_type, plaintext) in enumerate(pages, start=1):
        checksum = hashlib.md5(plaintext).hexdigest()  # noqa: S324
        row = AbdmDataTransfer(
            data_request=data_request,
            care_context=context,
            hi_type=hi_type,
            page_number=number,
            page_count=page_count,
            checksum=checksum,
        )
        if timezone.now() > data_request.deadline_at:
            ok, error = False, {"message": "Transfer deadline passed"}
        else:
            try:
                content, key_material = encrypt_for(
                    data_request.key_material, plaintext
                )
            except DataflowCryptoError as e:
                ok, error = False, {"message": str(e)}
            else:
                ok, error = _push(
                    data_request.data_push_url,
                    {
                        "pageNumber": number,
                        "pageCount": page_count,
                        "transactionId": data_request.transaction_id,
                        "entries": [
                            {
                                "content": content,
                                "media": MEDIA,
                                "checksum": checksum,
                                "careContextReference": context.reference_number,
                            }
                        ],
                        "keyMaterial": key_material,
                    },
                )
        row.status = "delivered" if ok else "failed"
        row.error = error
        row.save()
        status = statuses[context.reference_number]
        if ok:
            delivered += 1
            if status["description"] != "Delivery failed":
                status.update(hiStatus="DELIVERED", description="Delivered")
        else:
            status.update(hiStatus="ERRORED", description="Delivery failed")

    success = page_count > 0 and delivered == page_count
    data_request.status = "transferred" if success else "failed"
    if not success:
        data_request.error = {
            "message": "Nothing to transfer" if page_count == 0 else "Delivery failed",
            "pages": page_count,
            "delivered": delivered,
        }
    notify_row = reply(
        "hip.health_information_notify",
        NOTIFY_PATH,
        {
            "notification": {
                "consentId": consent.consent_id,
                "transactionId": data_request.transaction_id,
                "doneAt": iso(),
                "notifier": {"type": "HIP", "id": hip_id},
                "statusNotification": {
                    "sessionStatus": "TRANSFERRED" if success else "FAILED",
                    "hipId": hip_id,
                    "statusResponses": list(statuses.values()),
                },
            }
        },
        facility=consent.facility,
    )
    data_request.meta = {
        **data_request.meta,
        "notify_request_id": notify_row.request_id,
        "pages": page_count,
        "delivered": delivered,
    }
    data_request.save(update_fields=["status", "error", "meta", "modified_date"])
    logger.info(
        "ABDM HIP transfer %s: %s of %s pages delivered",
        data_request.transaction_id,
        delivered,
        page_count,
    )
