from django.db import transaction

from care.abdm.models import AbdmCareContext, AbdmDataRequest, AbdmFacility, AbhaNumber


@shared_task
def link_pending_care_contexts(abha_number_id: int, facility_id: int) -> None:
    from care.abdm.hip.linking import process_pending

    abha = AbhaNumber.objects.filter(id=abha_number_id).select_related("patient").first()
    config = AbdmFacility.objects.filter(id=facility_id).first()
    if abha and config:
        with transaction.atomic():
            process_pending(abha, config)


@shared_task
def notify_care_context(care_context_id: int, attempt: int = 0) -> None:
    from care.abdm.hip.linking import notify

    with transaction.atomic():
        context = (
            AbdmCareContext.objects.select_for_update()
            .filter(id=care_context_id, deleted=False)
            .select_related("abha_number__patient", "facility", "encounter__patient")
            .first()
        )
        if context:
            notify(context, attempt)


@shared_task
def transfer_health_information(data_request_id: int) -> None:
    from care.abdm.hip.dataflow import transfer

    with transaction.atomic():
        data_request = (
            AbdmDataRequest.objects.select_for_update()
            .filter(id=data_request_id, status="acknowledged")
            .select_related("consent__facility")
            .first()
        )
        if data_request:
            transfer(data_request)
