from decimal import Decimal, InvalidOperation

from django.utils import timezone

NRCES = "https://nrces.in/ndhm/fhir/r4/StructureDefinition/"
SNOMED = "http://snomed.info/sct"
UCUM = "http://unitsofmeasure.org"
V2_0203 = "http://terminology.hl7.org/CodeSystem/v2-0203"
# NRCES Patient/Organization examples; the portal names no system for either.
ABHA_SYSTEM = "https://healthid.ndhm.gov.in"
FACILITY_SYSTEM = "https://facility.ndhm.gov.in"
DOCUMENT_NAMESPACE = uuid.UUID("6f0d7d1c-7f0a-4f43-9a5e-3c6b0b3a7a10")

INPATIENT_CLASSES = {"imp", "obsenc", "emer"}

ENCOUNTER_STATUS = {
    "planned": "planned",
    "in_progress": "in-progress",
    "on_hold": "onleave",
    "discharged": "finished",
    "completed": "finished",
    "cancelled": "cancelled",
    "discontinued": "cancelled",
    "entered_in_error": "entered-in-error",
    "unknown": "unknown",
}
ENCOUNTER_CLASS = {
    "imp": "inpatient encounter",
    "amb": "ambulatory",
    "obsenc": "observation encounter",
    "emer": "emergency",
    "vr": "virtual",
    "hh": "home health",
}
GENDER = {"male": "male", "female": "female", "non_binary": "other"}


def fhir_code(value: str | None) -> str | None:
    return value.replace("_", "-") if value else None


def instant(value) -> str | None:
    return value.isoformat() if value else None


def number(value):
    if value is None or value == "":
        return None
    try:
        d = Decimal(str(value))
    except InvalidOperation:
        return None
    return int(d) if d == d.to_integral_value() else float(d)


def coding(value: dict | None) -> dict | None:
    """A Care Coding as a FHIR Coding; NRCES makes display mandatory."""
    if not value or not value.get("code"):
        return None
    out = {}
    if value.get("system"):
        out["system"] = value["system"]
    out["code"] = value["code"]
    out["display"] = value.get("display") or value["code"]
    return out


def concept(value: dict | None = None, text: str | None = None) -> dict | None:
    c = coding(value)
    out = {}
    if c:
        out["coding"] = [c]
    if text or (c and c.get("display")):
        out["text"] = text or c["display"]
    return out or None


def fixed_concept(system: str, code: str, display: str) -> dict:
    return {"coding": [{"system": system, "code": code, "display": display}]}


def quantity(value, unit: dict | None = None) -> dict | None:
    n = number(value)
    if n is None:
        return None
    out = {"value": n}
    if unit:
        if unit.get("display") or unit.get("code"):
            out["unit"] = unit.get("display") or unit["code"]
        if unit.get("system") and unit.get("code"):
            out["system"] = unit["system"]
            out["code"] = unit["code"]
    return out


def compact(resource: dict) -> dict:
    return {k: v for k, v in resource.items() if v not in (None, [], {}, "")}


def meta(profile: str, now) -> dict:
    return {"versionId": "1", "lastUpdated": instant(now), "profile": [NRCES + profile]}


class DocumentBuilder:
    """Collects the resources of one document Bundle, keyed by their logical fullUrl."""

    def __init__(self, care_context, hi_type: str, source_key: str = ""):
        self.care_context = care_context
        self.encounter = care_context.encounter
        self.patient = self.encounter.patient
        self.abdm_facility = care_context.facility
        self.facility = self.abdm_facility.facility
        self.hi_type = hi_type
        self.now = timezone.now()
        self.document_id = str(
            uuid.uuid5(
                DOCUMENT_NAMESPACE,
                f"{care_context.external_id}/{hi_type}/{source_key}",
            )
        )
        self.entries: dict[str, dict] = {}
        self.patient_ref = self.add(self._patient())
        self.organization_ref = self.add(self._organization())
        self.encounter_ref = self.add(self._encounter())

    def add(self, resource: dict) -> dict:
        key = f"{resource['resourceType']}/{resource['id']}"
        self.entries.setdefault(key, resource)
        return {"reference": key}

    def ref(self, resource: dict, display: str | None = None) -> dict:
        out = self.add(resource)
        if display:
            out["display"] = display
        return out

    def subject(self) -> dict:
        return {**self.patient_ref, "display": self._patient_name()}

    def practitioner(self, user) -> dict | None:
        if not user:
            return None
        if user.doctor_medical_council_registration:
            identifier = {
                "type": fixed_concept(V2_0203, "MD", "Medical License number"),
                "value": user.doctor_medical_council_registration,
            }
        else:
            identifier = {
                "type": fixed_concept(V2_0203, "EI", "Employee number"),
                "value": str(user.external_id),
            }
        name = user.full_name.strip() or user.username
        return self.ref(
            compact(
                {
                    "resourceType": "Practitioner",
                    "id": str(user.external_id),
                    "meta": meta("Practitioner", self.now),
                    "identifier": [identifier],
                    "name": [{"text": name}],
                }
            ),
            name,
        )

    def actor(self, user) -> dict:
        """A Practitioner reference for user, else the facility Organization."""
        return self.practitioner(user) or self.organization()

    def organization(self) -> dict:
        return {**self.organization_ref, "display": self._facility_name()}

    def author(self) -> dict:
        from care.users.models import User

        team = self.encounter.care_team if isinstance(self.encounter.care_team, list) else []
        user_ids = [m.get("user_id") for m in team if m.get("user_id")]
        user = User.objects.filter(id__in=user_ids[:1]).first() if user_ids else None
        return self.actor(user or self.encounter.created_by)

    def _patient_name(self) -> str:
        return self.patient.name or self.care_context.abha_number.name or "Patient"

    def _facility_name(self) -> str:
        return self.abdm_facility.display_name or self.facility.name

    def _patient(self) -> dict:
        abha = self.care_context.abha_number
        mr = fixed_concept(V2_0203, "MR", "Medical record number")
        identifiers = [{"type": mr, "system": ABHA_SYSTEM, "value": abha.abha_number}]
        if abha.abha_address:
            identifiers.append(
                {"type": mr, "system": ABHA_SYSTEM, "value": abha.abha_address}
            )
        p = self.patient
        birth = None
        if p.date_of_birth:
            birth = p.date_of_birth.isoformat()
        elif p.year_of_birth:
            birth = str(p.year_of_birth)
        return compact(
            {
                "resourceType": "Patient",
                "id": str(p.external_id),
                "meta": meta("Patient", self.now),
                "identifier": identifiers,
                "name": [{"text": self._patient_name()}],
                "telecom": (
                    [{"system": "phone", "value": p.phone_number, "use": "home"}]
                    if p.phone_number
                    else None
                ),
                "gender": GENDER.get(p.gender, "other" if p.gender else "unknown"),
                "birthDate": birth,
                "deceasedDateTime": instant(p.deceased_datetime),
            }
        )

    def _organization(self) -> dict:
        f = self.facility
        hip_id = self.abdm_facility.hip_id or self.abdm_facility.hfr_id
        return compact(
            {
                "resourceType": "Organization",
                "id": str(f.external_id),
                "meta": meta("Organization", self.now),
                "identifier": [
                    {
                        "type": fixed_concept(V2_0203, "PRN", "Provider number"),
                        "system": FACILITY_SYSTEM,
                        "value": hip_id,
                    }
                ],
                "name": self._facility_name(),
                "telecom": (
                    [{"system": "phone", "value": f.phone_number, "use": "work"}]
                    if f.phone_number
                    else None
                ),
            }
        )

    def _encounter(self) -> dict:
        e = self.encounter
        period = e.period or {}
        return compact(
            {
                "resourceType": "Encounter",
                "id": str(e.external_id),
                "meta": meta("Encounter", self.now),
                "identifier": [
                    {"system": "urn:ietf:rfc:3986", "value": f"urn:uuid:{e.external_id}"}
                ],
                "status": ENCOUNTER_STATUS.get(e.status, "unknown"),
                "class": {
                    "system": "http://terminology.hl7.org/CodeSystem/v3-ActCode",
                    "code": (e.encounter_class or "amb").upper(),
                    "display": ENCOUNTER_CLASS.get(e.encounter_class, "ambulatory"),
                },
                "subject": {**self.patient_ref, "display": self._patient_name()},
                "period": compact(
                    {"start": period.get("start"), "end": period.get("end")}
                )
                or {"start": instant(e.created_date)},
                "serviceProvider": self.organization(),
            }
        )

    def bundle(
        self,
        *,
        profile: str,
        type_code: str,
        type_display: str,
        title: str,
        sections: list[dict],
    ) -> dict | None:
        """sections: [{"title", "code": (code, display), "entry": [refs]}]; None if all empty."""
        sections = [s for s in sections if s["entry"]]
        if not sections:
            return None
        organization = self.organization()
        composition = {
            "resourceType": "Composition",
            "id": self.document_id,
            "meta": meta(profile, self.now),
            "language": "en-IN",
            "status": "final",
            "type": fixed_concept(SNOMED, type_code, type_display),
            "subject": self.subject(),
            "encounter": self.encounter_ref,
            "date": instant(self.now),
            "author": [self.author()],
            "title": title,
            "attester": [{"mode": "official", "party": organization}],
            "custodian": organization,
            "section": [
                {
                    "title": s["title"],
                    "code": fixed_concept(SNOMED, *s["code"]),
                    "entry": [
                        {"reference": r["reference"], "type": r["reference"].split("/")[0]}
                        for r in s["entry"]
                    ],
                }
                for s in sections
            ],
        }
        entries = [{"fullUrl": f"Composition/{self.document_id}", "resource": composition}]
        entries += [{"fullUrl": key, "resource": res} for key, res in self.entries.items()]
        return {
            "resourceType": "Bundle",
            "id": self.document_id,
            "meta": {
                "versionId": "1",
                "lastUpdated": instant(self.now),
                "profile": [NRCES + "DocumentBundle"],
                "security": [
                    {
                        "system": "http://terminology.hl7.org/CodeSystem/v3-Confidentiality",
                        "code": "V",
                        "display": "very restricted",
                    }
                ],
            },
            "identifier": {
                "system": "urn:ietf:rfc:3986",
                "value": f"urn:uuid:{self.document_id}",
            },
            "type": "document",
            "timestamp": instant(self.now),
            "entry": entries,
        }
