import uuid

from django.conf import settings
from django.shortcuts import get_object_or_404
from pydantic import BaseModel
from rest_framework.decorators import action
from rest_framework.exceptions import NotFound, PermissionDenied, ValidationError
from rest_framework.response import Response
from rest_framework.viewsets import GenericViewSet

from care.abdm.api.errors import abdm_exception_handler
from care.abdm.hip import linking
from care.abdm.hip.service import HipError
from care.abdm.models import AbdmCareContext, AbdmFacility, AbdmLinkToken, AbhaNumber
from care.emr.models import Encounter
from care.security.authorization import AuthorizationController

logger = logging.getLogger(__name__)


class LinkRequest(BaseModel):
    encounter: uuid.UUID
    hi_types: list[str] | None = None


class RetryRequest(BaseModel):
    care_context: uuid.UUID


def serialize_care_context(context: AbdmCareContext) -> dict:
    return {
        "id": str(context.external_id),
        "encounter": str(context.encounter.external_id),
        "reference_number": context.reference_number,
        "display": context.display,
        "hi_types": context.hi_types,
        "status": context.status,
        "linked_at": context.linked_at,
        "notified_at": context.notified_at,
        "linked_by": context.meta.get("linked_by", "hip"),
        "error": context.error,
        "modified_date": context.modified_date,
    }


def serialize_link_token(token: AbdmLinkToken | None) -> dict | None:
    if token is None:
        return None
    return {
        "status": token.status,
        "requested_at": token.requested_at,
        "expires_at": token.expires_at,
        "error": token.error,
    }


def _available_hi_types(encounter) -> list[str]:
    from care.abdm.fhir import available_hi_types

    try:
        return available_hi_types(encounter)
    except Exception:
        logger.exception("ABDM available_hi_types failed for encounter %s", encounter.id)
        return []


def encounter_state(encounter) -> dict:
    config = (
        AbdmFacility.objects.filter(facility=encounter.facility, deleted=False)
        .exclude(hip_id="")
        .first()
    )
    abha = AbhaNumber.objects.filter(patient=encounter.patient, deleted=False).first()
    token = (
        AbdmLinkToken.objects.filter(abha_number=abha, facility=config, deleted=False)
        .order_by("-id")
        .first()
        if abha and config
        else None
    )
    contexts = AbdmCareContext.objects.filter(
        encounter=encounter, deleted=False
    ).select_related("encounter")
    problems = []
    if config is None:
        problems.append("facility_not_configured")
    if abha is None:
        problems.append("patient_has_no_abha")
    return {
        "encounter": str(encounter.external_id),
        "ready": not problems,
        "problems": problems,
        "hip_id": config.hip_id if config else None,
        "abha_address": abha.abha_address if abha else None,
        "abha_number": abha.abha_number if abha else None,
        "available_hi_types": _available_hi_types(encounter),
        "link_token": serialize_link_token(token),
        "care_contexts": [serialize_care_context(c) for c in contexts],
    }


def _error(code: str, message: str, status: int = 400) -> Response:
    return Response(
        {"errors": [{"type": "abdm_error", "code": code, "msg": message}]},
        status=status,
    )


class CareContextViewSet(GenericViewSet):
    """Care contexts on an encounter: status, and HIP-initiated linking."""

    def get_exception_handler(self):
        return abdm_exception_handler

    def initial(self, request, *args, **kwargs):
        super().initial(request, *args, **kwargs)
        if not settings.ABDM_ENABLED:
            raise NotFound("ABDM is not enabled on this deployment")

    def _encounter(self, encounter_id, permission: str) -> Encounter:
        if not encounter_id:
            raise ValidationError({"encounter": "This parameter is required"})
        try:
            uuid.UUID(str(encounter_id))
        except ValueError as e:
            raise ValidationError({"encounter": "Not a valid id"}) from e
        encounter = get_object_or_404(
            Encounter.objects.select_related("patient", "facility"),
            external_id=encounter_id,
            deleted=False,
        )
        if not AuthorizationController.call(
            permission, self.request.user, encounter.patient
        ):
            raise PermissionDenied("You do not have permission on this patient")
        return encounter

    def list(self, request):
        encounter = self._encounter(
            request.query_params.get("encounter"), "can_view_patient_obj"
        )
        return Response(encounter_state(encounter))

    @action(detail=False, methods=["post"])
    def link(self, request):
        data = LinkRequest.model_validate(request.data)
        encounter = self._encounter(data.encounter, "can_write_patient_obj")
        try:
            linking.link_encounter(encounter, request.user, data.hi_types)
        except HipError as e:
            return _error(e.code, e.message)
        return Response(encounter_state(encounter))

    @action(detail=False, methods=["post"])
    def retry(self, request):
        data = RetryRequest.model_validate(request.data)
        context = get_object_or_404(
            AbdmCareContext.objects.select_related(
                "encounter__patient", "encounter__facility", "abha_number", "facility"
            ),
            external_id=data.care_context,
            deleted=False,
        )
        encounter = self._encounter(
            context.encounter.external_id, "can_write_patient_obj"
        )
        linking.retry(context)
        return Response(encounter_state(encounter))
