{"content": "from care.abdm.fhir.common import (
    SNOMED,
    UCUM,
    DocumentBuilder,
    compact,
    concept,
    fhir_code,
    fixed_concept,
    instant,
    meta,
    number,
    quantity,
)
from care.emr.models import (
    AllergyIntolerance,
    Condition,
    DiagnosticReport,
    MedicationRequest,
    Observation,
    ServiceRequest,
)

ERROR = "entered_in_error"
CONDITION_CLINICAL = "http://terminology.hl7.org/CodeSystem/condition-clinical"
CONDITION_VERIFICATION = "http://terminology.hl7.org/CodeSystem/condition-ver-status"
CONDITION_CLINICAL_CODES = {
    "active",
    "recurrence",
    "relapse",
    "inactive",
    "remission",
    "resolved",
}
SEVERITY = {
    "mild": ("255604002", "Mild"),
    "moderate": ("6736007", "Moderate"),
    "severe": ("24484000", "Severe"),
}
SERVICE_CATEGORY = {
    "laboratory": ("108252007", "Laboratory procedure"),
    "imaging": ("363679005", "Imaging"),
    "counselling": ("409063005", "Counseling"),
    "surgical_procedure": ("387713003", "Surgical procedure"),
    "education": ("409073007", "Education"),
}
MEDICATION_STATUS = {"ended": "completed", "on_hold": "on-hold"}
SERVICE_STATUS = {"ended": "completed", "on_hold": "on-hold"}
REPORT_STATUSES = ("final", "partial", "preliminary")


# Querysets: shared by the builders and the cheap existence checks.


def conditions(encounter, categories):
    return (
        Condition.objects.filter(encounter=encounter, category__in=categories)
        .exclude(verification_status=ERROR)
        .filter(code__has_key="code")
        .order_by("created_date")
    )


def observations(encounter):
    return (
        Observation.objects.filter(
            encounter=encounter, diagnostic_report__isnull=True, is_group=False
        )
        .exclude(status=ERROR)
        .filter(main_code__has_key="code")
        .order_by("effective_datetime", "created_date")
    )


def allergies(encounter):
    return (
        AllergyIntolerance.objects.filter(encounter=encounter)
        .exclude(verification_status=ERROR)
        .filter(code__has_key="code")
        .order_by("created_date")
    )


def medication_requests(encounter):
    return (
        MedicationRequest.objects.filter(encounter=encounter)
        .exclude(status__in=[ERROR, "draft"])
        .select_related("requester", "requested_product")
        .order_by("authored_on", "created_date")
    )


def service_requests(encounter):
    return (
        ServiceRequest.objects.filter(encounter=encounter)
        .exclude(status__in=[ERROR, "draft"])
        .select_related("requester")
        .order_by("created_date")
    )


def report_results(report):
    return (
        Observation.objects.filter(diagnostic_report=report, is_group=False)
        .exclude(status=ERROR)
        .filter(main_code__has_key="code")
        .order_by("effective_datetime", "created_date")
    )


def diagnostic_reports(encounter):
    return (
        DiagnosticReport.objects.filter(encounter=encounter, status__in=REPORT_STATUSES)
        .filter(
            observation__status__in=["final", "amended"],
            observation__main_code__has_key="code",
        )
        .distinct()
        .select_related("service_request", "created_by")
        .order_by("-modified_date")
    )


# Resources


def condition(b: DocumentBuilder, obj) -> dict:
    clinical = obj.clinical_status if obj.clinical_status in CONDITION_CLINICAL_CODES else None
    severity = SEVERITY.get(obj.severity)
    onset = obj.onset or {}
    resource = compact(
        {
            "resourceType": "Condition",
            "id": str(obj.external_id),
            "meta": meta("Condition", b.now),
            "clinicalStatus": (
                fixed_concept(CONDITION_CLINICAL, clinical, clinical.title())
                if clinical
                else None
            ),
            "verificationStatus": (
                fixed_concept(
                    CONDITION_VERIFICATION,
                    fhir_code(obj.verification_status),
                    obj.verification_status.replace("_", " ").title(),
                )
                if obj.verification_status
                else None
            ),
            "severity": fixed_concept(SNOMED, *severity) if severity else None,
            "code": concept(obj.code),
            "bodySite": [concept(obj.body_site)] if concept(obj.body_site) else None,
            "subject": b.subject(),
            "encounter": b.encounter_ref,
            "onsetDateTime": onset.get("onset_datetime"),
            "recordedDate": instant(obj.recorded_date),
            "note": [{"text": obj.note}] if obj.note else None,
        }
    )
    return b.ref(resource, resource["code"].get("text"))


def _observation_value(value_type: str, value: dict) -> dict:
    raw = value.get("value")
    if value.get("coding"):
        return {"valueCodeableConcept": concept(value["coding"])}
    if value_type in ("decimal", "integer", "quantity"):
        q = quantity(raw, value.get("unit"))
        if q and value.get("unit", {}) and value["unit"].get("system") is None:
            q.pop("system", None)
        return {"valueQuantity": q} if q else {}
    if value_type == "boolean" and raw is not None:
        return {"valueBoolean": str(raw).lower() in ("true", "1", "yes")}
    if value_type == "dateTime" and raw:
        return {"valueDateTime": raw}
    if raw not in (None, ""):
        return {"valueString": str(raw)}
    return {}


def observation(b: DocumentBuilder, obj) -> dict:
    value = obj.value if isinstance(obj.value, dict) else {}
    components = []
    for c in obj.component or []:
        code = concept(c.get("code"))
        if not code:
            continue
        components.append(
            {"code": code, **_observation_value(obj.value_type, c.get("value") or {})}
        )
    resource = compact(
        {
            "resourceType": "Observation",
            "id": str(obj.external_id),
            "meta": meta("Observation", b.now),
            "status": obj.status if obj.status in ("final", "amended") else "final",
            "category": [concept(obj.category)] if concept(obj.category) else None,
            "code": concept(obj.main_code),
            "subject": b.subject(),
            "encounter": b.encounter_ref,
            "effectiveDateTime": instant(obj.effective_datetime or obj.created_date),
            "performer": [b.actor(obj.data_entered_by or obj.created_by)],
            **_observation_value(obj.value_type, value),
            "interpretation": (
                [concept(obj.interpretation)] if concept(obj.interpretation) else None
            ),
            "note": [{"text": obj.note}] if obj.note else None,
            "bodySite": concept(obj.body_site),
            "method": concept(obj.method),
            "component": components,
        }
    )
    return b.ref(resource, resource["code"].get("text"))


def allergy(b: DocumentBuilder, obj) -> dict:
    base = "http://terminology.hl7.org/CodeSystem/allergyintolerance-"
    resource = compact(
        {
            "resourceType": "AllergyIntolerance",
            "id": str(obj.external_id),
            "meta": meta("AllergyIntolerance", b.now),
            "clinicalStatus": (
                fixed_concept(
                    base + "clinical",
                    obj.clinical_status,
                    obj.clinical_status.title(),
                )
                if obj.clinical_status
                else None
            ),
            "verificationStatus": (
                fixed_concept(
                    base + "verification",
                    fhir_code(obj.verification_status),
                    obj.verification_status.replace("_", " ").title(),
                )
                if obj.verification_status
                else None
            ),
            "type": obj.allergy_intolerance_type
            if obj.allergy_intolerance_type in ("allergy", "intolerance")
            else None,
            "category": [obj.category] if obj.category else None,
            "criticality": fhir_code(obj.criticality),
            "code": concept(obj.code),
            "patient": b.subject(),
            "encounter": b.encounter_ref,
            "onsetDateTime": (obj.onset or {}).get("onset_datetime"),
            "recordedDate": instant(obj.recorded_date or obj.created_date),
            "recorder": b.actor(obj.created_by),
            "note": [{"text": obj.note}] if obj.note else None,
        }
    )
    return b.ref(resource, resource["code"].get("text"))


def _duration(value: dict | None) -> dict | None:
    if not value:
        return None
    n = number(value.get("value"))
    unit = value.get("unit")
    if n is None or not unit:
        return None
    return {"value": n, "unit": unit, "system": UCUM, "code": unit}


def _dose(value: dict | None) -> dict | None:
    return quantity(value.get("value"), value.get("unit")) if value else None


def _dosage(instruction: dict) -> dict:
    timing = instruction.get("timing") or {}
    repeat = timing.get("repeat") or {}
    bounds_range = repeat.get("bounds_range") or {}
    dose = instruction.get("dose_and_rate") or {}
    dose_range = dose.get("dose_range") or {}
    max_dose = instruction.get("max_dose_per_period") or {}
    return compact(
        {
            "sequence": instruction.get("sequence"),
            "text": instruction.get("text"),
            "additionalInstruction": [
                c for c in map(concept, instruction.get("additional_instruction") or []) if c
            ],
            "patientInstruction": instruction.get("patient_instruction"),
            "timing": compact(
                {
                    "repeat": compact(
                        {
                            "frequency": number(repeat.get("frequency")),
                            "period": number(repeat.get("period")),
                            "periodUnit": repeat.get("period_unit"),
                            "boundsDuration": _duration(repeat.get("bounds_duration")),
                            "boundsRange": compact(
                                {
                                    "low": _duration(bounds_range.get("low")),
                                    "high": _duration(bounds_range.get("high")),
                                }
                            ),
                            "boundsPeriod": compact(repeat.get("bounds_period") or {}),
                        }
                    ),
                    "code": concept(timing.get("code")),
                }
            ),
            "asNeededBoolean": (
                instruction.get("as_needed_boolean")
                if not instruction.get("as_needed_for")
                else None
            ),
            "asNeededCodeableConcept": concept(instruction.get("as_needed_for")),
            "site": concept(instruction.get("site")),
            "route": concept(instruction.get("route")),
            "method": concept(instruction.get("method")),
            "doseAndRate": [
                compact(
                    {
                        "type": fixed_concept(
                            "http://terminology.hl7.org/CodeSystem/dose-rate-type",
                            dose["type"],
                            dose["type"].title(),
                        )
                        if dose.get("type")
                        else None,
                        "doseQuantity": _dose(dose.get("dose_quantity")),
                        "doseRange": compact(
                            {
                                "low": _dose(dose_range.get("low")),
                                "high": _dose(dose_range.get("high")),
                            }
                        ),
                    }
                )
            ]
            if dose
            else None,
            "maxDosePerPeriod": compact(
                {
                    "numerator": _dose(max_dose.get("high") or max_dose.get("low")),
                }
            )
            or None,
        }
    )


def medication_request(b: DocumentBuilder, obj) -> dict:
    product = obj.requested_product
    medication = concept(obj.medication) or (
        concept(product.code, product.name) if product else None
    )
    dosage = [d for d in map(_dosage, obj.dosage_instruction or []) if d]
    resource = compact(
        {
            "resourceType": "MedicationRequest",
            "id": str(obj.external_id),
            "meta": meta("MedicationRequest", b.now),
            "status": MEDICATION_STATUS.get(obj.status, fhir_code(obj.status) or "unknown"),
            "intent": fhir_code(obj.intent) or "order",
            "category": (
                [
                    fixed_concept(
                        "http://terminology.hl7.org/CodeSystem/medicationrequest-category",
                        obj.category,
                        obj.category.title(),
                    )
                ]
                if obj.category
                else None
            ),
            "priority": obj.priority,
            "doNotPerform": obj.do_not_perform or None,
            "medicationCodeableConcept": medication or {"text": "Medication"},
            "subject": b.subject(),
            "encounter": b.encounter_ref,
            "authoredOn": instant(obj.authored_on or obj.created_date),
            "requester": b.actor(obj.requester or obj.created_by),
            "note": [{"text": obj.note}] if obj.note else None,
            "dosageInstruction": dosage
            or [{"text": obj.note or (medication or {}).get("text") or "As directed"}],
        }
    )
    return b.ref(resource, resource["medicationCodeableConcept"].get("text"))


def service_request(b: DocumentBuilder, obj) -> dict:
    category = SERVICE_CATEGORY.get(obj.category)
    resource = compact(
        {
            "resourceType": "ServiceRequest",
            "id": str(obj.external_id),
            "meta": meta("ServiceRequest", b.now),
            "status": SERVICE_STATUS.get(obj.status, fhir_code(obj.status) or "unknown"),
            "intent": obj.intent or "order",
            "category": [fixed_concept(SNOMED, *category)] if category else None,
            "priority": obj.priority,
            "doNotPerform": obj.do_not_perform or None,
            "code": concept(obj.code, obj.title),
            "subject": b.subject(),
            "encounter": b.encounter_ref,
            "occurrenceDateTime": instant(obj.occurance),
            "authoredOn": instant(obj.created_date),
            "requester": b.actor(obj.requester or obj.created_by),
            "bodySite": [concept(obj.body_site)] if concept(obj.body_site) else None,
            "note": [{"text": obj.note}] if obj.note else None,
            "patientInstruction": obj.patient_instruction,
        }
    )
    return b.ref(resource, obj.title or None)


def diagnostic_report(b: DocumentBuilder, obj) -> dict:
    imaging = obj.service_request and obj.service_request.category == "imaging"
    results = [observation(b, o) for o in report_results(obj)]
    resource = compact(
        {
            "resourceType": "DiagnosticReport",
            "id": str(obj.external_id),
            "meta": meta(
                "DiagnosticReportImaging" if imaging else "DiagnosticReportLab", b.now
            ),
            "basedOn": (
                [service_request(b, obj.service_request)] if obj.service_request else None
            ),
            "status": obj.status,
            "category": [concept(obj.category)] if concept(obj.category) else None,
            "code": concept(obj.code)
            or concept(
                obj.service_request.code if obj.service_request else None,
                obj.service_request.title if obj.service_request else "Diagnostic report",
            ),
            "subject": b.subject(),
            "encounter": b.encounter_ref,
            "issued": instant(obj.modified_date),
            "performer": [b.organization()],
            "resultsInterpreter": [b.actor(obj.created_by)],
            "result": results,
            "conclusion": obj.conclusion or obj.note,
        }
    )
    return b.ref(resource, resource["code"].get("text"))
