from care.abdm.fhir.common import INPATIENT_CLASSES, DocumentBuilder

HI_TYPE = "OPConsultation"


def _querysets(encounter):
    return {
        "chief": r.conditions(encounter, ["problem_list_item"]),
        "history": r.conditions(encounter, ["chronic_condition"]),
        "allergies": r.allergies(encounter),
        "exam": r.observations(encounter),
        "medications": r.medication_requests(encounter),
        "orders": r.service_requests(encounter),
    }


def has_data(encounter) -> bool:
    if encounter.encounter_class in INPATIENT_CLASSES:
