from care.abdm.fhir.common import DocumentBuilder

HI_TYPE = "DiagnosticReport"


def has_data(encounter) -> bool:
    return r.diagnostic_reports(encounter).exists()


def build(care_context) -> list[dict]:
    """One bundle per report: DiagnosticReportRecord allows 1 section with 1 report."""
    bundles = []
    for report in r.diagnostic_reports(care_context.encounter):
        b = DocumentBuilder(care_context, HI_TYPE, str(report.external_id))
        entry = r.diagnostic_report(b, report)
        bundle = b.bundle(
            profile="DiagnosticReportRecord",
            type_code="721981007",
            type_display="Diagnostic studies report",
            title=entry.get("display") or "Diagnostic Report",
            sections=[
                {
                    "title": entry.get("display") or "Diagnostic Report",
                    "code": ("721981007", "Diagnostic studies report"),
                    "entry": [entry],
                }
            ],
        )
        if bundle:
            bundles.append(bundle)
    return bundles
