    """
    record = RECORDS.get(hi_type)
    return record.build(care_context) if record else []


def build_bundle(care_context, hi_type: str) -> dict | None:
    """The FHIR document Bundle for one care context and HI type, or None if empty."""
    bundles = build_bundles(care_context, hi_type)
    return bundles[0] if bundles else None


def available_hi_types(encounter) -> list[str]:
    return [t for t, record in RECORDS.items() if record.has_data(encounter)]
