import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";

import { AbdmErrorMessage } from "@/components/Abdm/utils";

export default function AbdmErrorAlert({
  error,
  className,
}: {
  error: AbdmErrorMessage;
  className?: string;
}) {
  const { t } = useTranslation();
  return (
    <Alert
      variant={error.transient ? "default" : "destructive"}
      role="alert"
      className={className}
    >
      <AlertTitle>{error.message}</AlertTitle>
      <AlertDescription className="flex flex-col gap-1 text-xs">
        {error.detail && <span className="break-words">{error.detail}</span>}
        {error.fields.length > 0 && (
          <span>
            {t("abha_field_refused_hint", { fields: error.fields.join(", ") })}
          </span>
        )}
        {(error.code || error.requestId) && (
          <span className="font-mono">
            {[
              error.code,
              error.requestId && t("abdm_error_ref", { ref: error.requestId }),
            ]
              .filter(Boolean)
              .join(" · ")}
          </span>
        )}
      </AlertDescription>
    </Alert>
  );
}
