{"content": "import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import {
  CheckCircle2Icon,
  CircleXIcon,
  RefreshCwIcon,
  ShieldOffIcon,
} from "lucide-react";
import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { EmptyState } from "@/components/ui/empty-state";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Skeleton } from "@/components/ui/skeleton";
import { Switch } from "@/components/ui/switch";

import AbdmErrorAlert from "@/components/Abdm/AbdmErrorAlert";
import {
  AbdmErrorMessage,
  getAbdmError,
  useAbdmConfig,
} from "@/components/Abdm/utils";
import PageHeadTitle from "@/components/Common/PageHeadTitle";

import { getPermissions } from "@/common/Permissions";

import { usePermissions } from "@/context/PermissionContext";
import useCurrentFacility from "@/pages/Facility/utils/useCurrentFacility";
import {
  AbdmBridgeService,
  AbdmFacilityConfigUpdate,
  AbdmFacilitySyncResponse,
} from "@/types/abdm/facility";
import facilityAbdmApi from "@/types/abdm/facilityApi";
import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";
import { formatDateTime } from "@/Utils/utils";

interface AbdmSettingsProps {
  facilityId: string;
}

const EMPTY_FORM: AbdmFacilityConfigUpdate = {
  hfr_id: "",
  hip_id: "",
  hiu_id: "",
  is_hip: false,
  is_hiu: false,
  display_name: "",
};

export function AbdmSettings({ facilityId }: AbdmSettingsProps) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const { enabled } = useAbdmConfig();
  const { facility } = useCurrentFacility();
  const { hasPermission } = usePermissions();
  const { canUpdateFacility } = getPermissions(
    hasPermission,
    facility?.permissions ?? [],
  );

  const [form, setForm] = useState<AbdmFacilityConfigUpdate>(EMPTY_FORM);
  const [sync, setSync] = useState<AbdmFacilitySyncResponse | null>(null);
  const [error, setError] = useState<AbdmErrorMessage | null>(null);

  const configKey = ["abdm", "facility", facilityId];
  const bridgeKey = ["abdm", "facility", facilityId, "bridge"];

  const {
    data: config,
    isLoading,
    error: configError,
  } = useQuery({
    queryKey: configKey,
    queryFn: query(facilityAbdmApi.get, {
      pathParams: { facility: facilityId },
      silent: true,
    }),
    enabled,
  });

  const {
    data: bridge,
    isFetching: isBridgeFetching,
    error: bridgeError,
    refetch: refetchBridge,
  } = useQuery({
    queryKey: bridgeKey,
    queryFn: query(facilityAbdmApi.bridge, {
      queryParams: { facility: facilityId },
      silent: true,
    }),
    enabled: enabled && canUpdateFacility,
    retry: false,
  });

  useEffect(() => {
    if (config) {
      setForm({
        hfr_id: config.hfr_id,
        hip_id: config.hip_id,
        hiu_id: config.hiu_id,
        is_hip: config.is_hip,
        is_hiu: config.is_hiu,
        display_name: config.display_name,
      });
    }
  }, [config]);

  const { mutate: runSync, isPending: isSyncing } = useMutation({
    mutationFn: mutate(facilityAbdmApi.sync, { silent: true }),
    onSuccess: (data) => {
      setError(null);
      setSync(data);
    },
    onError: (e) => setError(getAbdmError(e, t("abdm_sync_failed"))),
  });

  const { mutate: save, isPending: isSaving } = useMutation({
    mutationFn: mutate(facilityAbdmApi.update, {
      pathParams: { facility: facilityId },
      silent: true,
    }),
    onSuccess: (data) => {
      setError(null);
      queryClient.setQueryData(configKey, data);
      queryClient.invalidateQueries({ queryKey: bridgeKey });
      toast.success(t("abdm_settings_saved"));
    },
    onError: (e) => setError(getAbdmError(e, t("abdm_settings_save_failed"))),
  });

  if (!enabled) {
    return (
      <EmptyState
        icon={<ShieldOffIcon className="size-8 text-gray-400" />}
        title={t("abdm_not_enabled")}
        description={t("abdm_not_enabled_description")}
      />
    );
  }

  const services = sync?.services ?? bridge?.services ?? [];
  const hipServices = services.filter((s) => s.types?.includes("HIP"));
  const hiuServices = services.filter((s) => s.types?.includes("HIU"));
  const suggestion = sync?.suggestion;

  const handleApplySuggestion = () => {
    if (!suggestion) return;
    setForm((prev) => ({
      ...prev,
      hip_id: suggestion.hip_id || prev.hip_id,
      hiu_id: suggestion.hiu_id || prev.hiu_id,
      is_hip: suggestion.is_hip || prev.is_hip,
      is_hiu: suggestion.is_hiu || prev.is_hiu,
      display_name: prev.display_name || suggestion.display_name,
    }));
  };

  const handleSave = () => {
    setError(null);
    save(form);
  };

  return (
    <div className="space-y-6 text-neutral-950">
      <PageHeadTitle title={t("abdm_settings")} />
      <div>
        <h1 className="text-3xl leading-9 font-bold tracking-tight">
          {t("abdm_settings")}
        </h1>
        <p className="mt-1 text-sm text-gray-600">
          {t("abdm_settings_description")}
        </p>
      </div>

      {configError && (
        <AbdmErrorAlert
          error={getAbdmError(configError, t("abdm_settings_load_failed"))}
        />
      )}

      {canUpdateFacility && (
        <Card>
          <CardHeader className="flex flex-row items-start justify-between gap-2">
            <div className="space-y-1.5">
              <CardTitle>{t("abdm_readiness")}</CardTitle>
              <CardDescription>
                {t("abdm_readiness_description")}
              </CardDescription>
            </div>
            <Button
              variant="outline"
              size="sm"
              onClick={() => refetchBridge()}
              disabled={isBridgeFetching}
            >
              <RefreshCwIcon
                className={isBridgeFetching ? "animate-spin" : undefined}
              />
              {t("abdm_recheck")}
            </Button>
          </CardHeader>
          <CardContent className="space-y-3">
            {bridgeError && (
              <AbdmErrorAlert
                error={getAbdmError(bridgeError, t("abdm_readiness_failed"))}
              />
            )}
            {!bridge && isBridgeFetching ? (
              <Skeleton className="h-32 w-full" />
            ) : (
              bridge && (
                <>
                  <dl className="grid grid-cols-1 gap-x-4 gap-y-2 text-sm md:grid-cols-2">
                    <div>
                      <dt className="text-gray-600">
                        {t("abdm_expected_bridge_url")}
                      </dt>
                      <dd className="font-mono break-all">
                        {bridge.expected_bridge_url || "-"}
                      </dd>
                    </div>
                    <div>
                      <dt className="text-gray-600">
                        {t("abdm_registered_bridge_url")}
                      </dt>
                      <dd className="font-mono break-all">
                        {bridge.registered_bridge_url || "-"}
                      </dd>
                    </div>
                  </dl>
                  <ul className="divide-y divide-gray-100 rounded-md border border-gray-200">
                    {bridge.readiness.map((item) => (
                      <li
                        key={item.check}
                        className="flex items-start gap-2 px-3 py-2 text-sm"
                      >
                        {item.ok ? (
                          <CheckCircle2Icon
                            className="mt-0.5 size-4 shrink-0 text-green-600"
                            aria-label={t("abdm_check_passed")}
                          />
                        ) : (
                          <CircleXIcon
                            className="mt-0.5 size-4 shrink-0 text-red-600"
                            aria-label={t("abdm_check_failed")}
                          />
                        )}
                        <div className="min-w-0">
                          <div className="font-medium">
                            {t(`abdm_readiness_${item.check}`)}
                          </div>
                          {item.detail && (
                            <div className="text-xs text-gray-600 font-mono break-all">
                              {item.detail}
                            </div>
                          )}
                        </div>
                      </li>
                    ))}
                  </ul>
                </>
              )
            )}
          </CardContent>
        </Card>
      )}

      <Card>
        <CardHeader className="flex flex-row items-start justify-between gap-2">
          <div className="space-y-1.5">
            <CardTitle>{t("abdm_services")}</CardTitle>
            <CardDescription>
              {config?.last_synced_at
                ? t("abdm_last_synced", {
                    date: formatDateTime(config.last_synced_at),
                  })
                : t("abdm_services_description")}
            </CardDescription>
          </div>
          {canUpdateFacility && (
            <Button
              variant="outline"
              size="sm"
              onClick={() => runSync({ facility: facilityId })}
              disabled={isSyncing}
            >
              <RefreshCwIcon className={isSyncing ? "animate-spin" : undefined} />
              {t("abdm_fetch_services")}
            </Button>
          )}
        </CardHeader>
        <CardContent className="space-y-5">
          {error && <AbdmErrorAlert error={error} />}

          {suggestion && (
            <div className="flex flex-wrap items-center justify-between gap-2 rounded-md border border-blue-200 bg-blue-50 p-3 text-sm">
              <span>
                {t("abdm_service_suggestion", {
                  name: suggestion.display_name,
                  id: suggestion.hip_id || suggestion.hiu_id,
                  matched_by: t(`abdm_matched_by_${suggestion.matched_by}`),
                })}
              </span>
              <Button size="sm" variant="outline" onClick={handleApplySuggestion}>
                {t("abdm_apply_suggestion")}
              </Button>
            </div>
          )}
          {sync && services.length === 0 && (
            <p className="text-sm text-gray-600">{t("abdm_no_services")}</p>
          )}

          {isLoading ? (
            <Skeleton className="h-48 w-full" />
          ) : (
            <>
              <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
                <div className="space-y-1.5">
                  <Label htmlFor="abdm-hfr-id">{t("abdm_hfr_id")}</Label>
                  <Input
                    id="abdm-hfr-id"
                    value={form.hfr_id}
                    maxLength={64}
                    disabled={!canUpdateFacility}
                    onChange={(e) =>
                      setForm((prev) => ({ ...prev, hfr_id: e.target.value }))
                    }
                  />
                </div>
                <div className="space-y-1.5">
                  <Label htmlFor="abdm-display-name">
                    {t("abdm_display_name")}
                  </Label>
                  <Input
                    id="abdm-display-name"
                    value={form.display_name}
                    maxLength={255}
                    disabled={!canUpdateFacility}
                    onChange={(e) =>
                      setForm((prev) => ({
                        ...prev,
                        display_name: e.target.value,
                      }))
                    }
                  />
                </div>
              </div>

              <ServiceRoleSection
                id="hip"
                title={t("abdm_hip")}
                description={t("abdm_hip_description")}
                checked={form.is_hip}
                serviceId={form.hip_id}
                services={hipServices}
                disabled={!canUpdateFacility}
                onCheckedChange={(is_hip) =>
                  setForm((prev) => ({ ...prev, is_hip }))
                }
                onServiceIdChange={(hip_id) =>
                  setForm((prev) => ({ ...prev, hip_id }))
                }
              />
              <ServiceRoleSection
                id="hiu"
                title={t("abdm_hiu")}
                description={t("abdm_hiu_description")}
                checked={form.is_hiu}
                serviceId={form.hiu_id}
                services={hiuServices}
                disabled={!canUpdateFacility}
                onCheckedChange={(is_hiu) =>
                  setForm((prev) => ({ ...prev, is_hiu }))
                }
                onServiceIdChange={(hiu_id) =>
                  setForm((prev) => ({ ...prev, hiu_id }))
                }
              />

              {canUpdateFacility && (
                <div className="flex justify-end">
                  <Button
                    variant="primary"
                    onClick={handleSave}
                    disabled={isSaving}
                  >
                    {isSaving ? t("saving") : t("save")}
                  </Button>
                </div>
              )}
            </>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

interface ServiceRoleSectionProps {
  id: string;
  title: string;
  description: string;
  checked: boolean;
  serviceId: string;
  services: AbdmBridgeService[];
  disabled: boolean;
  onCheckedChange: (checked: boolean) => void;
  onServiceIdChange: (serviceId: string) => void;
}

function ServiceRoleSection({
  id,
  title,
  description,
  checked,
  serviceId,
  services,
  disabled,
  onCheckedChange,
  onServiceIdChange,
}: ServiceRoleSectionProps) {
  const { t } = useTranslation();
  return (
    <section className="space-y-3 rounded-md border border-gray-200 p-4">
      <div className="flex items-start justify-between gap-4">
        <div>
          <Label htmlFor={`abdm-is-${id}`} className="text-base font-semibold">
            {title}
          </Label>
          <p className="text-sm text-gray-600">{description}</p>
        </div>
        <Switch
          id={`abdm-is-${id}`}
          checked={checked}
          disabled={disabled}
          onCheckedChange={onCheckedChange}
        />
      </div>
      {checked && (
        <div className="space-y-3">
          <div className="space-y-1.5">
            <Label htmlFor={`abdm-${id}-id`}>{t("abdm_service_id")}</Label>
            <Input
              id={`abdm-${id}-id`}
              value={serviceId}
              maxLength={64}
              disabled={disabled}
              className="font-mono"
              onChange={(e) => onServiceIdChange(e.target.value)}
            />
          </div>
          {services.length > 0 && (
            <RadioGroup
              value={serviceId}
              onValueChange={onServiceIdChange}
              disabled={disabled}
              aria-label={t("abdm_bridge_services")}
              className="gap-2"
            >
              {services.map((service) => (
                <Label
                  key={service.id}
                  htmlFor={`abdm-${id}-${service.id}`}
                  className="flex cursor-pointer items-center gap-3 rounded-md border border-gray-200 p-2 font-normal"
                >
                  <RadioGroupItem
                    id={`abdm-${id}-${service.id}`}
                    value={service.id}
                  />
                  <span className="min-w-0 flex-1">
                    <span className="block font-medium">
                      {service.name || service.id}
                    </span>
                    <span className="block font-mono text-xs text-gray-600">
                      {service.id}
                    </span>
                  </span>
                  <Badge variant={service.active ? "green" : "secondary"}>
                    {service.active ? t("active") : t("inactive")}
                  </Badge>
                </Label>
              ))}
            </RadioGroup>
          )}
        </div>
      )}
    </section>
  );
}
