import { LinkIcon, Loader2Icon, RotateCcwIcon, ShieldCheckIcon } from "lucide-react";
import { Link } from "raviger";
import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import { Label } from "@/components/ui/label";
import { Skeleton } from "@/components/ui/skeleton";

import AbdmErrorAlert from "@/components/Abdm/AbdmErrorAlert";
import {
  AbdmErrorMessage,
  fromStoredAbdmError,
  getAbdmError,
  useAbdmConfig,
} from "@/components/Abdm/utils";

import {
  AbdmCareContext,
  AbdmCareContextStatus,
  AbdmEncounterState,
  AbdmHiType,
} from "@/types/abdm/careContext";
import careContextApi from "@/types/abdm/careContextApi";
import { EncounterRead } from "@/types/emr/encounter/encounter";
import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";
import { formatDateTime } from "@/Utils/utils";

const POLL_INTERVAL_MS = 3000;
const POLL_TIMEOUT_MS = 2 * 60 * 1000;

const STATUS_VARIANT: Record<
  AbdmCareContextStatus,
  "secondary" | "blue" | "green" | "destructive"
> = {
  pending: "secondary",
  linking: "blue",
  linked: "green",
  failed: "destructive",
};

function isInProgress(state?: AbdmEncounterState) {
  if (!state) return false;
  return (
    state.link_token?.status === "requested" ||
    state.care_contexts.some(
      (c) => c.status === "pending" || c.status === "linking",
    )
  );
}

interface EncounterAbdmCardProps {
  encounter: EncounterRead;
  canWrite: boolean;
}

export default function EncounterAbdmCard({
  encounter,
  canWrite,
}: EncounterAbdmCardProps) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const { enabled } = useAbdmConfig();
  const [selected, setSelected] = useState<AbdmHiType[] | null>(null);
  const [error, setError] = useState<AbdmErrorMessage | null>(null);
  const [timedOut, setTimedOut] = useState(false);

  const queryKey = ["abdm", "care_context", encounter.id];
  const {
    data: state,
    isLoading,
    error: loadError,
  } = useQuery({
    queryKey,
    queryFn: query(careContextApi.state, {
      queryParams: { encounter: encounter.id },
      silent: true,
    }),
    enabled,
    retry: false,
    refetchInterval: (q) =>
      isInProgress(q.state.data) && !timedOut ? POLL_INTERVAL_MS : false,
  });

  const inProgress = isInProgress(state);

  useEffect(() => {
    if (!inProgress) {
      setTimedOut(false);
      return;
    }
    const timer = setTimeout(() => setTimedOut(true), POLL_TIMEOUT_MS);
    return () => clearTimeout(timer);
  }, [inProgress]);

  const onUpdated = (data: AbdmEncounterState) => {
    setError(null);
    setTimedOut(false);
    queryClient.setQueryData(queryKey, data);
  };

  const { mutate: link, isPending: isLinking } = useMutation({
    mutationFn: mutate(careContextApi.link, { silent: true }),
    onSuccess: onUpdated,
    onError: (e) => setError(getAbdmError(e, t("abdm_link_failed"))),
  });

  const { mutate: retry, isPending: isRetrying } = useMutation({
    mutationFn: mutate(careContextApi.retry, { silent: true }),
    onSuccess: onUpdated,
    onError: (e) => setError(getAbdmError(e, t("abdm_retry_failed"))),
  });

  if (!enabled) {
    return null;
  }

  const available = state?.available_hi_types ?? [];
  const hiTypes = selected ?? available;
  const facilityId = encounter.facility.id;
  const patientId = encounter.patient.id;

  const handleToggle = (type: AbdmHiType, checked: boolean) => {
    setSelected(
      checked ? [...hiTypes, type] : hiTypes.filter((h) => h !== type),
    );
  };

  const handleLink = () => {
    setError(null);
    link({ encounter: encounter.id, hi_types: hiTypes });
  };

  return (
    <Card className="rounded-sm shadow-sm">
      <CardHeader className="flex flex-row items-center justify-between gap-2 space-y-0">
        <CardTitle className="flex items-center gap-2 text-base font-semibold">
          <ShieldCheckIcon className="size-5 text-primary-700" />
          {t("abdm")}
        </CardTitle>
        {inProgress && !timedOut && (
          <span className="flex items-center gap-1 text-xs text-gray-600">
            <Loader2Icon className="size-3 animate-spin" />
            {t("abdm_waiting_on_abdm")}
          </span>
        )}
      </CardHeader>
      <CardContent className="space-y-4">
        {isLoading && <Skeleton className="h-20 w-full" />}
        {loadError && (
          <AbdmErrorAlert
            error={getAbdmError(loadError, t("abdm_care_context_load_failed"))}
          />
        )}
        {error && <AbdmErrorAlert error={error} />}

        {state && (
          <>
            {state.problems.includes("facility_not_configured") && (
              <Alert>
                <AlertDescription className="flex flex-wrap items-center gap-2">
                  {t("abdm_problem_facility_not_configured")}
                  <Link
                    href={`/facility/${facilityId}/settings/abdm`}
                    className="font-medium text-primary-700 underline"
                  >
                    {t("abdm_open_facility_settings")}
                  </Link>
                </AlertDescription>
              </Alert>
            )}
            {state.problems.includes("patient_has_no_abha") && (
              <Alert>
                <AlertDescription className="flex flex-wrap items-center gap-2">
                  {t("abdm_problem_patient_has_no_abha")}
                  <Link
                    href={`/facility/${facilityId}/patient/${patientId}/demography`}
                    className="font-medium text-primary-700 underline"
                  >
                    {t("abdm_open_patient_page")}
                  </Link>
                </AlertDescription>
              </Alert>
            )}

            {state.abha_address && (
              <p className="text-sm text-gray-700">
                {t("abdm_linking_to", { address: state.abha_address })}
              </p>
            )}

            {state.link_token?.status === "failed" && (
              <AbdmErrorAlert
                error={fromStoredAbdmError(
                  state.link_token.error,
                  t("abdm_link_token_failed"),
                )}
              />
            )}

            {state.care_contexts.length > 0 && (
              <ul className="space-y-3">
                {state.care_contexts.map((context) => (
                  <CareContextItem
                    key={context.id}
                    context={context}
                    canRetry={canWrite && !isRetrying}
                    onRetry={() => {
                      setError(null);
                      retry({ care_context: context.id });
                    }}
                  />
                ))}
              </ul>
            )}

            {inProgress && timedOut && (
              <p className="text-sm text-gray-600" role="status">
                {t("abdm_still_waiting")}
              </p>
            )}

            {canWrite && state.ready && (
              <div className="space-y-3 rounded-md border border-gray-200 p-3">
                {available.length === 0 ? (
                  <p className="text-sm text-gray-600">
                    {t("abdm_no_hi_types_available")}
                  </p>
                ) : (
                  <fieldset className="space-y-2">
                    <legend className="mb-1 text-sm font-medium">
                      {t("abdm_hi_types_to_share")}
                    </legend>
                    <div className="flex flex-wrap gap-x-4 gap-y-2">
                      {available.map((type) => (
                        <div key={type} className="flex items-center gap-2">
                          <Checkbox
                            id={`abdm-hi-${encounter.id}-${type}`}
                            checked={hiTypes.includes(type)}
                            onCheckedChange={(checked) =>
                              handleToggle(type, checked === true)
                            }
                          />
                          <Label
                            htmlFor={`abdm-hi-${encounter.id}-${type}`}
                            className="font-normal"
                          >
                            {t(`abdm_hi_type_${type}`)}
                          </Label>
                        </div>
                      ))}
                    </div>
                  </fieldset>
                )}
                <Button
                  variant="primary"
                  size="sm"
                  onClick={handleLink}
                  disabled={
                    isLinking ||
                    (inProgress && !timedOut) ||
                    hiTypes.length === 0
                  }
                >
                  {isLinking ? (
                    <Loader2Icon className="animate-spin" />
                  ) : (
                    <LinkIcon />
                  )}
                  {state.care_contexts.length > 0
                    ? t("abdm_relink_to_abha")
                    : t("abdm_link_to_abha")}
                </Button>
              </div>
            )}
          </>
        )}
      </CardContent>
    </Card>
  );
}

function CareContextItem({
  context,
  canRetry,
  onRetry,
}: {
  context: AbdmCareContext;
  canRetry: boolean;
  onRetry: () => void;
}) {
  const { t } = useTranslation();
  return (
    <li className="space-y-2 rounded-md border border-gray-200 p-3">
      <div className="flex flex-wrap items-start justify-between gap-2">
        <div className="min-w-0">
          <div className="text-sm font-medium">{context.display}</div>
          <div className="font-mono text-xs text-gray-600">
            {context.reference_number}
          </div>
        </div>
        <Badge variant={STATUS_VARIANT[context.status]}>
          {t(`abdm_care_context_status_${context.status}`)}
        </Badge>
      </div>
      <ul
        className="flex flex-wrap gap-1"
        aria-label={t("abdm_hi_types_to_share")}
      >
        {context.hi_types.map((type) => (
          <li key={type}>
            <Badge variant={STATUS_VARIANT[context.status]} size="xs">
              {t(`abdm_hi_type_${type}`)}
            </Badge>
          </li>
        ))}
      </ul>
      {(context.linked_at || context.notified_at) && (
        <div className="flex flex-wrap gap-x-4 text-xs text-gray-600">
          {context.linked_at && (
            <span>
              {t("abdm_linked_at", { date: formatDateTime(context.linked_at) })}
            </span>
          )}
          {context.notified_at && (
            <span>
              {t("abdm_notified_at", {
                date: formatDateTime(context.notified_at),
              })}
            </span>
          )}
        </div>
      )}
      {context.status === "failed" && (
        <div className="space-y-2">
          <AbdmErrorAlert
            error={{
              ...fromStoredAbdmError(context.error, t("abdm_link_failed")),
              detail: context.error?.stage
                ? t("abdm_failed_at_stage", {
                    stage: t(`abdm_stage_${context.error.stage}`),
                  })
                : undefined,
            }}
          />
          {canRetry && (
            <Button variant="outline" size="sm" onClick={onRetry}>
              <RotateCcwIcon />
              {t("retry")}
            </Button>
          )}
        </div>
      )}
    </li>
  );
}
