{"content": "import { FhirBundle, FhirResource } from "@/types/abdm/consent";

interface Coding {
  code?: string;
  display?: string;
}

interface CodeableConcept {
  text?: string;
  coding?: Coding[];
}

interface Quantity {
  value?: number;
  unit?: string;
  code?: string;
}

interface Reference {
  reference?: string;
  display?: string;
}

export interface CompositionSection {
  title?: string;
  code?: CodeableConcept;
  entry?: Reference[];
}

export interface FhirComposition extends FhirResource {
  resourceType: "Composition";
  title?: string;
  date?: string;
  section?: CompositionSection[];
}

export interface FhirMedicationRequest extends FhirResource {
  resourceType: "MedicationRequest";
  status?: string;
  authoredOn?: string;
  medicationCodeableConcept?: CodeableConcept;
  medicationReference?: Reference;
  dosageInstruction?: { text?: string }[];
}

export interface FhirObservation extends FhirResource {
  resourceType: "Observation";
  status?: string;
  code?: CodeableConcept;
  effectiveDateTime?: string;
  valueQuantity?: Quantity;
  valueString?: string;
  valueCodeableConcept?: CodeableConcept;
  valueBoolean?: boolean;
  valueInteger?: number;
  component?: {
    code?: CodeableConcept;
    valueQuantity?: Quantity;
    valueString?: string;
  }[];
}

export interface FhirCondition extends FhirResource {
  resourceType: "Condition";
  code?: CodeableConcept;
  clinicalStatus?: CodeableConcept;
  recordedDate?: string;
}

export interface FhirDiagnosticReport extends FhirResource {
  resourceType: "DiagnosticReport";
  status?: string;
  code?: CodeableConcept;
  conclusion?: string;
  issued?: string;
}

export function codeableText(concept?: CodeableConcept | null) {
  if (!concept) return undefined;
  const coding = concept.coding?.[0];
  return concept.text || coding?.display || coding?.code;
}

export function quantityText(quantity?: Quantity) {
  if (!quantity || quantity.value === undefined) return undefined;
  return [quantity.value, quantity.unit || quantity.code]
    .filter((v) => v !== undefined && v !== "")
    .join(" ");
}

export function observationValue(observation: FhirObservation) {
  const value =
    quantityText(observation.valueQuantity) ??
    observation.valueString ??
    codeableText(observation.valueCodeableConcept) ??
    observation.valueInteger?.toString() ??
    observation.valueBoolean?.toString();
  if (value !== undefined) return value;
  const parts = (observation.component ?? [])
    .map((c) => {
      const componentValue = quantityText(c.valueQuantity) ?? c.valueString;
      const label = codeableText(c.code);
      return componentValue && label ? `${label}: ${componentValue}` : undefined;
    })
    .filter(Boolean);
  return parts.length ? parts.join(", ") : undefined;
}

/** A label for any resource: its code, name or title, whichever it carries. */
export function resourceLabel(resource: FhirResource) {
  const r = resource as FhirResource & {
    code?: CodeableConcept;
    title?: string;
    name?: string | { text?: string; given?: string[]; family?: string }[];
    type?: CodeableConcept | CodeableConcept[];
    description?: string;
  };
  if (typeof r.name === "string") return r.name;
  if (Array.isArray(r.name) && r.name[0]) {
    const name = r.name[0];
    return (
      name.text || [...(name.given ?? []), name.family].filter(Boolean).join(" ")
    );
  }
  const type = Array.isArray(r.type) ? r.type[0] : r.type;
  return codeableText(r.code) || r.title || codeableText(type) || r.description;
}

export function bundleResources(bundle: FhirBundle | null) {
  return (bundle?.entry ?? [])
    .map((entry) => entry.resource)
    .filter((resource): resource is FhirResource => !!resource?.resourceType);
}
