{"content": "import { ChevronDownIcon, CodeIcon } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";

import {
  FhirComposition,
  FhirCondition,
  FhirDiagnosticReport,
  FhirMedicationRequest,
  FhirObservation,
  bundleResources,
  codeableText,
  observationValue,
  resourceLabel,
} from "@/components/Abdm/fhir";

import {
  AbdmFetchedRecord,
  FhirBundle,
  FhirResource,
} from "@/types/abdm/consent";
import { formatDateTime } from "@/Utils/utils";

// Resources that only give context to the clinical ones; listed by count, not rendered.
const CONTEXT_RESOURCES = new Set([
  "Composition",
  "Patient",
  "Practitioner",
  "PractitionerRole",
  "Organization",
  "Encounter",
]);

export default function AbdmRecordCard({
  record,
}: {
  record: AbdmFetchedRecord;
}) {
  const { t } = useTranslation();
  const [open, setOpen] = useState(false);
  const [showRaw, setShowRaw] = useState(false);
  const summary = record.summary;
  const title =
    summary?.title || summary?.type || t("abdm_record_untitled");

  return (
    <article className="rounded-md border border-gray-200 bg-white p-3">
      <div className="flex flex-wrap items-start justify-between gap-2">
        <div className="min-w-0">
          <h4 className="font-semibold">{title}</h4>
          <div className="flex flex-wrap gap-x-3 text-xs text-gray-600">
            {summary?.type && summary.type !== title && (
              <span>{summary.type}</span>
            )}
            {summary?.date && <span>{formatDateTime(summary.date)}</span>}
            {summary?.status && <span>{summary.status}</span>}
          </div>
        </div>
        {record.checksum_ok === false && (
          <Badge variant="destructive">{t("abdm_checksum_mismatch")}</Badge>
        )}
      </div>

      {summary && Object.keys(summary.resource_types).length > 0 && (
        <ul className="mt-2 flex flex-wrap gap-1" aria-label={t("abdm_resources")}>
          {Object.entries(summary.resource_types).map(([kind, count]) => (
            <li key={kind}>
              <Badge variant="secondary" size="xs">
                {t("abdm_resource_count", { type: kind, count })}
              </Badge>
            </li>
          ))}
        </ul>
      )}
      {record.error && (
        <p className="mt-2 text-xs text-red-600" role="alert">
          {record.error}
        </p>
      )}

      <Collapsible open={open} onOpenChange={setOpen} className="mt-2">
        <div className="flex flex-wrap gap-2">
          <CollapsibleTrigger asChild>
            <Button variant="ghost" size="sm" aria-expanded={open}>
              <ChevronDownIcon
                className={open ? "rotate-180 transition" : "transition"}
              />
              {open ? t("abdm_hide_details") : t("abdm_show_details")}
            </Button>
          </CollapsibleTrigger>
          <Button
            variant="ghost"
            size="sm"
            aria-pressed={showRaw}
            onClick={() => setShowRaw((v) => !v)}
          >
            <CodeIcon />
            {showRaw ? t("abdm_hide_raw_json") : t("abdm_view_raw_json")}
          </Button>
        </div>
        <CollapsibleContent className="mt-2">
          <BundleView bundle={record.bundle} />
        </CollapsibleContent>
      </Collapsible>
      {showRaw && (
        <pre className="mt-2 max-h-96 overflow-auto rounded-md bg-gray-900 p-3 text-xs text-gray-100">
          {JSON.stringify(record.bundle, null, 2)}
        </pre>
      )}
    </article>
  );
}

function referenceKeys(entryUrl: string | undefined, resource: FhirResource) {
  const keys = [`${resource.resourceType}/${resource.id}`];
  if (entryUrl) keys.push(entryUrl);
  return keys;
}

function BundleView({ bundle }: { bundle: FhirBundle | null }) {
  const { t } = useTranslation();
  const resources = bundleResources(bundle);
  const byReference = new Map<string, FhirResource>();
  (bundle?.entry ?? []).forEach((entry) => {
    if (entry.resource?.resourceType) {
      referenceKeys(entry.fullUrl, entry.resource).forEach((key) =>
        byReference.set(key, entry.resource as FhirResource),
      );
    }
  });
  const composition = resources.find(
    (r): r is FhirComposition => r.resourceType === "Composition",
  );
  const sections = composition?.section ?? [];

  if (sections.length > 0) {
    return (
      <div className="space-y-3">
        {sections.map((section, index) => {
          const items = (section.entry ?? [])
            .map((ref) => (ref.reference ? byReference.get(ref.reference) : undefined))
            .filter((r): r is FhirResource => !!r);
          return (
            <section key={index} className="space-y-1">
              <h5 className="text-sm font-semibold text-gray-800">
                {section.title || codeableText(section.code) || t("abdm_section")}
              </h5>
              {items.length === 0 ? (
                <p className="text-xs text-gray-600">{t("abdm_no_entries")}</p>
              ) : (
                <ul className="space-y-1">
                  {items.map((resource, i) => (
                    <FhirResourceItem key={resource.id ?? i} resource={resource} />
                  ))}
                </ul>
              )}
            </section>
          );
        })}
      </div>
    );
  }

  const clinical = resources.filter((r) => !CONTEXT_RESOURCES.has(r.resourceType));
  if (clinical.length === 0) {
    return <p className="text-xs text-gray-600">{t("abdm_no_entries")}</p>;
  }
  return (
    <ul className="space-y-1">
      {clinical.map((resource, i) => (
        <FhirResourceItem key={resource.id ?? i} resource={resource} />
      ))}
    </ul>
  );
}

function Field({ label, value }: { label: string; value?: string }) {
  if (!value) return null;
  return (
    <span className="block text-xs text-gray-700">
      <span className="text-gray-500">{label}: </span>
      {value}
    </span>
  );
}

function FhirResourceItem({ resource }: { resource: FhirResource }) {
  const { t } = useTranslation();
  let title = resourceLabel(resource);
  let body: React.ReactNode = null;

  switch (resource.resourceType) {
    case "MedicationRequest": {
      const r = resource as FhirMedicationRequest;
      title =
        codeableText(r.medicationCodeableConcept) ||
        r.medicationReference?.display ||
        title;
      body = (
        <>
          <Field
            label={t("abdm_fhir_dosage")}
            value={(r.dosageInstruction ?? [])
              .map((d) => d.text)
              .filter(Boolean)
              .join("; ")}
          />
          <Field
            label={t("abdm_fhir_authored_on")}
            value={r.authoredOn && formatDateTime(r.authoredOn)}
          />
        </>
      );
      break;
    }
    case "Observation": {
      const r = resource as FhirObservation;
      body = (
        <>
          <Field label={t("abdm_fhir_value")} value={observationValue(r)} />
          <Field
            label={t("abdm_fhir_date")}
            value={r.effectiveDateTime && formatDateTime(r.effectiveDateTime)}
          />
        </>
      );
      break;
    }
    case "Condition": {
      const r = resource as FhirCondition;
      body = (
        <Field
          label={t("abdm_fhir_clinical_status")}
          value={codeableText(r.clinicalStatus)}
        />
      );
      break;
    }
    case "DiagnosticReport": {
      const r = resource as FhirDiagnosticReport;
      body = (
        <>
          <Field label={t("abdm_fhir_conclusion")} value={r.conclusion} />
          <Field
            label={t("abdm_fhir_date")}
            value={r.issued && formatDateTime(r.issued)}
          />
        </>
      );
      break;
    }
  }

  return (
    <li className="rounded border border-gray-100 bg-gray-50 px-2 py-1.5">
      <span className="flex flex-wrap items-center gap-2 text-sm">
        <Badge variant="outline" size="xs">
          {resource.resourceType}
        </Badge>
        <span className="font-medium">{title || "-"}</span>
      </span>
      {body}
    </li>
  );
}
