{"content": "import { useMutation, useQueryClient } from "@tanstack/react-query";
import { addDays, format, subYears } from "date-fns";
import { useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";

import AbdmErrorAlert from "@/components/Abdm/AbdmErrorAlert";
import { AbdmErrorMessage, getAbdmError } from "@/components/Abdm/utils";

import { ABDM_HI_TYPES, AbdmHiType } from "@/types/abdm/careContext";
import { ABDM_PURPOSES, AbdmPurpose } from "@/types/abdm/consent";
import consentApi from "@/types/abdm/consentApi";
import mutate from "@/Utils/request/mutate";

const DATE_FORMAT = "yyyy-MM-dd";

function startOfDayIso(date: string) {
  return new Date(`${date}T00:00:00`).toISOString();
}

function endOfDayIso(date: string) {
  return new Date(`${date}T23:59:59`).toISOString();
}

function initialForm() {
  const today = new Date();
  return {
    purpose: "CAREMGT" as AbdmPurpose,
    hiTypes: [...ABDM_HI_TYPES] as AbdmHiType[],
    dateFrom: format(subYears(today, 1), DATE_FORMAT),
    dateTo: format(today, DATE_FORMAT),
    dataEraseAt: format(addDays(today, 30), DATE_FORMAT),
    hipId: "",
  };
}

interface RequestAbdmRecordsSheetProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  patientId: string;
  facilityId: string;
  listQueryKey: unknown[];
}

export default function RequestAbdmRecordsSheet({
  open,
  onOpenChange,
  patientId,
  facilityId,
  listQueryKey,
}: RequestAbdmRecordsSheetProps) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [form, setForm] = useState(initialForm);
  const [error, setError] = useState<AbdmErrorMessage | null>(null);

  const { mutate: create, isPending } = useMutation({
    mutationFn: mutate(consentApi.create, { silent: true }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: listQueryKey });
      toast.success(t("abdm_consent_requested"));
      setForm(initialForm());
      onOpenChange(false);
    },
    onError: (e) => {
      // A gateway failure still records the request; show it in the list.
      queryClient.invalidateQueries({ queryKey: listQueryKey });
      setError(getAbdmError(e, t("abdm_consent_request_failed")));
    },
  });

  const today = format(new Date(), DATE_FORMAT);
  const invalidRange = !form.dateFrom || !form.dateTo || form.dateFrom > form.dateTo;
  const invalidErase = !form.dataEraseAt || form.dataEraseAt <= today;
  const canSubmit =
    form.hiTypes.length > 0 && !invalidRange && !invalidErase && !isPending;

  const handleToggle = (type: AbdmHiType, checked: boolean) => {
    setForm((prev) => ({
      ...prev,
      hiTypes: checked
        ? [...prev.hiTypes, type]
        : prev.hiTypes.filter((h) => h !== type),
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!canSubmit) return;
    setError(null);
    create({
      patient: patientId,
      facility: facilityId,
      purpose: form.purpose,
      hi_types: form.hiTypes,
      date_from: startOfDayIso(form.dateFrom),
      date_to: endOfDayIso(form.dateTo),
      data_erase_at: endOfDayIso(form.dataEraseAt),
      hip_id: form.hipId.trim() || undefined,
    });
  };

  return (
    <Sheet
      open={open}
      onOpenChange={(next) => {
        if (!next) setError(null);
        onOpenChange(next);
      }}
    >
      <SheetContent className="flex w-full flex-col gap-0 overflow-y-auto sm:max-w-lg">
        <SheetHeader>
          <SheetTitle>{t("abdm_request_records")}</SheetTitle>
          <SheetDescription>
            {t("abdm_request_records_description")}
          </SheetDescription>
        </SheetHeader>
        <form onSubmit={handleSubmit} className="mt-4 flex flex-col gap-4">
          {error && <AbdmErrorAlert error={error} />}

          <div className="space-y-1.5">
            <Label htmlFor="abdm-purpose">{t("abdm_purpose")}</Label>
            <Select
              value={form.purpose}
              onValueChange={(purpose) =>
                setForm((prev) => ({ ...prev, purpose: purpose as AbdmPurpose }))
              }
            >
              <SelectTrigger id="abdm-purpose">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {ABDM_PURPOSES.map((purpose) => (
                  <SelectItem key={purpose} value={purpose}>
                    {t(`abdm_purpose_${purpose}`)}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <fieldset className="space-y-2">
            <legend className="mb-1 text-sm font-medium">
              {t("abdm_hi_types")}
            </legend>
            {ABDM_HI_TYPES.map((type) => (
              <div key={type} className="flex items-center gap-2">
                <Checkbox
                  id={`abdm-request-${type}`}
                  checked={form.hiTypes.includes(type)}
                  onCheckedChange={(checked) =>
                    handleToggle(type, checked === true)
                  }
                />
                <Label htmlFor={`abdm-request-${type}`} className="font-normal">
                  {t(`abdm_hi_type_${type}`)}
                </Label>
              </div>
            ))}
            {form.hiTypes.length === 0 && (
              <p className="text-xs text-red-600" role="alert">
                {t("abdm_choose_hi_type")}
              </p>
            )}
          </fieldset>

          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label htmlFor="abdm-date-from">{t("abdm_date_from")}</Label>
              <Input
                id="abdm-date-from"
                type="date"
                value={form.dateFrom}
                max={today}
                onChange={(e) =>
                  setForm((prev) => ({ ...prev, dateFrom: e.target.value }))
                }
              />
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="abdm-date-to">{t("abdm_date_to")}</Label>
              <Input
                id="abdm-date-to"
                type="date"
                value={form.dateTo}
                max={today}
                onChange={(e) =>
                  setForm((prev) => ({ ...prev, dateTo: e.target.value }))
                }
              />
            </div>
            {invalidRange && (
              <p className="col-span-2 text-xs text-red-600" role="alert">
                {t("abdm_invalid_date_range")}
              </p>
            )}
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="abdm-erase-at">{t("abdm_data_erase_at")}</Label>
            <Input
              id="abdm-erase-at"
              type="date"
              value={form.dataEraseAt}
              min={today}
              onChange={(e) =>
                setForm((prev) => ({ ...prev, dataEraseAt: e.target.value }))
              }
            />
            <p className="text-xs text-gray-600">
              {t("abdm_data_erase_at_help")}
            </p>
            {invalidErase && (
              <p className="text-xs text-red-600" role="alert">
                {t("abdm_invalid_erase_at")}
              </p>
            )}
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="abdm-hip-id">{t("abdm_hip_id_optional")}</Label>
            <Input
              id="abdm-hip-id"
              value={form.hipId}
              maxLength={64}
              className="font-mono"
              onChange={(e) =>
                setForm((prev) => ({ ...prev, hipId: e.target.value }))
              }
            />
            <p className="text-xs text-gray-600">{t("abdm_hip_id_help")}</p>
          </div>

          <SheetFooter className="mt-2 gap-2">
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
            >
              {t("cancel")}
            </Button>
            <Button type="submit" variant="primary" disabled={!canSubmit}>
              {isPending ? t("abdm_requesting") : t("abdm_send_request")}
            </Button>
          </SheetFooter>
        </form>
      </SheetContent>
    </Sheet>
  );
}
