{"content": "import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import {
  FileTextIcon,
  Loader2Icon,
  PlusIcon,
  RefreshCwIcon,
  ShieldCheckIcon,
} from "lucide-react";
import { Link } from "raviger";
import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { EmptyState } from "@/components/ui/empty-state";
import { Progress } from "@/components/ui/progress";
import { Skeleton } from "@/components/ui/skeleton";

import AbdmErrorAlert from "@/components/Abdm/AbdmErrorAlert";
import AbdmRecordCard from "@/components/Abdm/AbdmRecordCard";
import RequestAbdmRecordsSheet from "@/components/Abdm/RequestAbdmRecordsSheet";
import {
  AbdmErrorMessage,
  fromStoredAbdmError,
  getAbdmError,
  useAbdmConfig,
} from "@/components/Abdm/utils";
import { PatientProps } from "@/components/Patient/PatientDetailsTab";

import abhaApi from "@/types/abdm/abhaApi";
import {
  AbdmConsentArtefact,
  AbdmConsentRequest,
  AbdmConsentStatus,
  AbdmTransferStatus,
} from "@/types/abdm/consent";
import consentApi from "@/types/abdm/consentApi";
import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";
import { formatDateTime, formatName } from "@/Utils/utils";

const POLL_INTERVAL_MS = 5000;
const POLL_TIMEOUT_MS = 2 * 60 * 1000;

const CONSENT_VARIANT: Record<
  AbdmConsentStatus,
  "secondary" | "blue" | "green" | "destructive" | "yellow"
> = {
  PENDING: "secondary",
  REQUESTED: "blue",
  GRANTED: "green",
  DENIED: "destructive",
  EXPIRED: "yellow",
  REVOKED: "yellow",
  FAILED: "destructive",
};

const TRANSFER_ACTIVE: AbdmTransferStatus[] = [
  "requested",
  "acknowledged",
  "receiving",
];

function isActive(requests?: AbdmConsentRequest[]) {
  return (requests ?? []).some(
    (r) =>
      r.status === "PENDING" ||
      r.artefacts.some(
        (a) => a.transfer && TRANSFER_ACTIVE.includes(a.transfer.status),
      ),
  );
}

export function PatientAbdmRecords({ facilityId, patientId }: PatientProps) {
  const { t } = useTranslation();
  const { enabled } = useAbdmConfig();
  const [sheetOpen, setSheetOpen] = useState(false);
  const [timedOut, setTimedOut] = useState(false);

  const { data: abha, isLoading: isAbhaLoading } = useQuery({
    queryKey: ["abdm", "patient", patientId],
    // 404 here only means no ABHA is linked yet.
    queryFn: query(abhaApi.patient, {
      queryParams: { patient: patientId },
      silent: true,
    }),
    enabled,
    retry: false,
  });

  const listQueryKey = ["abdm", "consent_request", patientId];
  const {
    data,
    isLoading,
    error: listError,
  } = useQuery({
    queryKey: listQueryKey,
    queryFn: query(consentApi.list, {
      queryParams: { patient: patientId },
      silent: true,
    }),
    enabled: enabled && !!abha,
    retry: false,
    refetchInterval: (q) =>
      isActive(q.state.data?.results) && !timedOut ? POLL_INTERVAL_MS : false,
  });

  const active = isActive(data?.results);
  useEffect(() => {
    if (!active) {
      setTimedOut(false);
      return;
    }
    const timer = setTimeout(() => setTimedOut(true), POLL_TIMEOUT_MS);
    return () => clearTimeout(timer);
  }, [active]);

  if (!enabled) {
    return null;
  }

  if (isAbhaLoading) {
    return <Skeleton className="mt-4 h-40 w-full" />;
  }

  if (!abha) {
    return (
      <EmptyState
        className="mt-4"
        icon={<ShieldCheckIcon className="size-8 text-gray-400" />}
        title={t("abdm_records_need_abha")}
        description={t("abdm_records_need_abha_description")}
        action={
          <Button variant="outline" asChild>
            <Link
              href={
                facilityId
                  ? `/facility/${facilityId}/patient/${patientId}/demography`
                  : `/patient/${patientId}/demography`
              }
            >
              {t("abdm_open_patient_page")}
            </Link>
          </Button>
        }
      />
    );
  }

  const requests = data?.results ?? [];

  return (
    <section className="mt-4 space-y-4" aria-labelledby="abdm-records-title">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div>
          <h2 id="abdm-records-title" className="text-lg font-semibold">
            {t("abdm_records")}
          </h2>
          <p className="text-sm text-gray-600">
            {t("abdm_records_description", { address: abha.abha_address })}
          </p>
        </div>
        <div className="flex flex-col items-end gap-1">
          <Button
            variant="primary"
            onClick={() => setSheetOpen(true)}
            disabled={!facilityId}
          >
            <PlusIcon />
            {t("abdm_request_records")}
          </Button>
          {!facilityId && (
            <span className="text-xs text-gray-600">
              {t("abdm_request_needs_facility")}
            </span>
          )}
        </div>
      </div>

      {listError && (
        <AbdmErrorAlert
          error={getAbdmError(listError, t("abdm_consent_list_failed"))}
        />
      )}
      {active && timedOut && (
        <p className="text-sm text-gray-600" role="status">
          {t("abdm_still_waiting")}
        </p>
      )}

      {isLoading ? (
        <Skeleton className="h-40 w-full" />
      ) : requests.length === 0 ? (
        !listError && (
          <EmptyState
            icon={<FileTextIcon className="size-8 text-gray-400" />}
            title={t("abdm_no_consent_requests")}
            description={t("abdm_no_consent_requests_description")}
          />
        )
      ) : (
        <ul className="space-y-3">
          {requests.map((request) => (
            <li key={request.id}>
              <ConsentRequestCard
                request={request}
                listQueryKey={listQueryKey}
              />
            </li>
          ))}
        </ul>
      )}

      {facilityId && (
        <RequestAbdmRecordsSheet
          open={sheetOpen}
          onOpenChange={setSheetOpen}
          patientId={patientId}
          facilityId={facilityId}
          listQueryKey={listQueryKey}
        />
      )}
    </section>
  );
}

function ConsentRequestCard({
  request,
  listQueryKey,
}: {
  request: AbdmConsentRequest;
  listQueryKey: unknown[];
}) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [showRecords, setShowRecords] = useState(false);
  const [error, setError] = useState<AbdmErrorMessage | null>(null);

  const { mutate: refresh, isPending: isRefreshing } = useMutation({
    mutationFn: mutate(consentApi.refresh, {
      pathParams: { id: request.id },
      silent: true,
    }),
    onSuccess: () => {
      setError(null);
      // ABDM answers the status call by callback; the list poll picks it up.
      queryClient.invalidateQueries({ queryKey: listQueryKey });
    },
    onError: (e) => setError(getAbdmError(e, t("abdm_refresh_failed"))),
  });

  const recordCount = request.artefacts.reduce(
    (sum, a) => sum + a.record_count,
    0,
  );

  return (
    <Card className="rounded-sm shadow-sm">
      <CardHeader className="flex flex-row flex-wrap items-start justify-between gap-2 space-y-0">
        <div className="min-w-0 space-y-1">
          <CardTitle className="flex flex-wrap items-center gap-2 text-base">
            {t(`abdm_purpose_${request.purpose}`)}
            <Badge variant={CONSENT_VARIANT[request.status]}>
              {t(`abdm_consent_status_${request.status}`)}
            </Badge>
          </CardTitle>
          <div className="flex flex-wrap gap-x-4 text-xs text-gray-600">
            <span>
              {t("abdm_requested_on", {
                date: formatDateTime(request.created_date),
              })}
            </span>
            {request.requester && (
              <span>
                {t("abdm_requested_by", {
                  name: formatName(request.requester) || request.requester.username,
                })}
              </span>
            )}
          </div>
        </div>
        <div className="flex flex-wrap gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => {
              setError(null);
              refresh({});
            }}
            disabled={isRefreshing || !request.consent_request_id}
          >
            <RefreshCwIcon className={isRefreshing ? "animate-spin" : undefined} />
            {t("abdm_refresh_status")}
          </Button>
          {recordCount > 0 && (
            <Button
              variant="outline"
              size="sm"
              aria-expanded={showRecords}
              onClick={() => setShowRecords((v) => !v)}
            >
              <FileTextIcon />
              {showRecords
                ? t("abdm_hide_records")
                : t("abdm_view_records", { count: recordCount })}
            </Button>
          )}
        </div>
      </CardHeader>
      <CardContent className="space-y-3">
        {error && <AbdmErrorAlert error={error} />}
        {request.status === "FAILED" && request.error && (
          <AbdmErrorAlert
            error={fromStoredAbdmError(
              request.error,
              t("abdm_consent_request_failed"),
            )}
          />
        )}
        {request.reason && (
          <p className="text-sm text-gray-700">
            {t("abdm_consent_reason", { reason: request.reason })}
          </p>
        )}

        <dl className="grid grid-cols-1 gap-x-4 gap-y-2 text-sm md:grid-cols-3">
          <div>
            <dt className="text-gray-600">{t("abdm_date_range")}</dt>
            <dd>
              {formatDateTime(request.date_from, "DD/MM/YYYY")} –{" "}
              {formatDateTime(request.date_to, "DD/MM/YYYY")}
            </dd>
          </div>
          <div>
            <dt className="text-gray-600">{t("abdm_data_erase_at")}</dt>
            <dd>{formatDateTime(request.data_erase_at)}</dd>
          </div>
          <div>
            <dt className="text-gray-600">{t("abdm_hip")}</dt>
            <dd className="font-mono">{request.hip_id || t("abdm_any_hip")}</dd>
          </div>
          <div className="md:col-span-3">
            <dt className="text-gray-600">{t("abdm_hi_types")}</dt>
            <dd className="mt-1 flex flex-wrap gap-1">
              {request.hi_types.map((type) => (
                <Badge key={type} variant="secondary" size="xs">
                  {t(`abdm_hi_type_${type}`)}
                </Badge>
              ))}
            </dd>
          </div>
        </dl>

        {request.artefacts.length > 0 && (
          <div className="space-y-2">
            <h3 className="text-sm font-semibold">{t("abdm_artefacts")}</h3>
            <ul className="space-y-2">
              {request.artefacts.map((artefact) => (
                <ArtefactItem key={artefact.id} artefact={artefact} />
              ))}
            </ul>
          </div>
        )}

        {showRecords && <ConsentRecords consentRequestId={request.id} />}
      </CardContent>
    </Card>
  );
}

function ArtefactItem({ artefact }: { artefact: AbdmConsentArtefact }) {
  const { t } = useTranslation();
  const transfer = artefact.transfer;
  const expected = transfer?.expected_pages ?? 0;
  const received = transfer?.received_pages ?? 0;
  const transferActive = !!transfer && TRANSFER_ACTIVE.includes(transfer.status);

  return (
    <li className="space-y-2 rounded-md border border-gray-200 p-3 text-sm">
      <div className="flex flex-wrap items-start justify-between gap-2">
        <div className="min-w-0">
          <div className="font-medium">{artefact.hip_name || artefact.hip_id}</div>
          <div className="font-mono text-xs text-gray-600">
            {artefact.hip_id}
          </div>
        </div>
        <div className="flex flex-wrap gap-1">
          <Badge variant="outline">{artefact.status}</Badge>
          {transfer && (
            <Badge
              variant={
                transfer.status === "received"
                  ? "green"
                  : transfer.status === "failed"
                    ? "destructive"
                    : "blue"
              }
            >
              {transferActive && <Loader2Icon className="size-3 animate-spin" />}
              {t(`abdm_transfer_status_${transfer.status}`)}
            </Badge>
          )}
        </div>
      </div>
      {transfer && expected > 0 && (
        <div className="space-y-1">
          <Progress
            value={Math.min(100, (received / expected) * 100)}
            aria-label={t("abdm_pages_received", { received, expected })}
          />
          <span className="text-xs text-gray-600">
            {t("abdm_pages_received", { received, expected })}
          </span>
        </div>
      )}
      <div className="text-xs text-gray-600">
        {t("abdm_record_count", { count: artefact.record_count })}
      </div>
      {artefact.fetch_error && (
        <AbdmErrorAlert
          error={fromStoredAbdmError(
            artefact.fetch_error,
            t("abdm_fetch_failed"),
          )}
        />
      )}
      {transfer?.status === "failed" && transfer.error && (
        <AbdmErrorAlert
          error={fromStoredAbdmError(transfer.error, t("abdm_transfer_failed"))}
        />
      )}
    </li>
  );
}

function ConsentRecords({ consentRequestId }: { consentRequestId: string }) {
  const { t } = useTranslation();
  const { data, isLoading, error } = useQuery({
    queryKey: ["abdm", "consent_request", consentRequestId, "records"],
    queryFn: query(consentApi.records, {
      pathParams: { id: consentRequestId },
      silent: true,
    }),
    retry: false,
  });

  if (isLoading) {
    return <Skeleton className="h-32 w-full" />;
  }
  if (error) {
    return (
      <AbdmErrorAlert error={getAbdmError(error, t("abdm_records_failed"))} />
    );
  }
  if (!data?.artefacts.length) {
    return <p className="text-sm text-gray-600">{t("abdm_no_records")}</p>;
  }

  return (
    <div className="space-y-4">
      {data.artefacts.map((artefact) => (
        <section
          key={artefact.id}
          className="space-y-3 rounded-md bg-gray-50 p-3"
        >
          <h3 className="text-sm font-semibold">
            {artefact.hip_name || artefact.hip_id}
            {artefact.data_erase_at && (
              <span className="ml-2 text-xs font-normal text-gray-600">
                {t("abdm_erased_on", {
                  date: formatDateTime(artefact.data_erase_at),
                })}
              </span>
            )}
          </h3>
          {artefact.care_contexts.map((context) => (
            <div key={context.care_context_reference} className="space-y-2">
              <h4 className="font-mono text-xs text-gray-600">
                {t("abdm_care_context_ref", {
                  ref: context.care_context_reference,
                })}
              </h4>
              {context.records.map((record) => (
                <AbdmRecordCard key={record.id} record={record} />
              ))}
            </div>
          ))}
        </section>
      ))}
    </div>
  );
}
