def _header(callback: AbdmCallback, name: str) -> str:
    name = name.lower()
    for key, value in (callback.headers or {}).items():
        if key.lower() == name:
            return str(value)
    return ""


def _fail_rejected_request(callback: AbdmCallback, notification: dict) -> bool:
    """ABDM can refuse a consent request outright (e.g. ABDM-1120, no care
    context): it skips on-init and sends notify with an error and a
    consentRequestId Care never received. Nothing in it echoes our request id,
    so pin it to the newest still-unacknowledged request of that HIU (L12)."""
    error = callback_error(callback.body)
    hiu_id = _header(callback, "X-HIU-ID")
    if not error or not hiu_id:
        return False
    consent_request = (
        AbdmConsentRequest.objects.filter(
            facility__hiu_id=hiu_id,
            status="PENDING",
            consent_request_id__isnull=True,
            created_date__gte=timezone.now() - REJECTION_MATCH_WINDOW,
        )
        .order_by("-created_date")
        .first()
    )
    if consent_request is None:
        return False
    complete_outbound(consent_request.request_id)
    consent_request.consent_request_id = str(
        notification.get("consentRequestId") or ""
    )[:64] or None
    consent_request.status = "FAILED"
    consent_request.error = error
    consent_request.save(update_fields=["consent_request_id", "status", "error"])
    return True


def on_notify(callback: AbdmCallback) -> None:
    notification = callback.body.get("notification") or {}
    consent_request = AbdmConsentRequest.objects.filter(
        consent_request_id=str(notification.get("consentRequestId") or "")
    ).first()
    if consent_request is None:
        if _fail_rejected_request(callback, notification):
            return
        raise CallbackNotReady("consent request not yet acknowledged")"}

