{"filePath": "/Users/rithviknishad/ohc.network/care/care/abdm/management/commands/abdm_register_bridge.py", "content": "from django.core.management.base import BaseCommand, CommandError

from care.abdm.service import bridge


def _registered_url() -> str:
    row = bridge.list_bridge_services()
    if not row.ok:
        msg = f"Reading the bridge failed: {row.error_code} {row.error_message} (ref {row.request_id})"
        raise CommandError(msg)
    body = row.response_body or {}
    return str((body.get("bridge") or {}).get("url") or "")


class Command(BaseCommand):
    help = (
        "Register this deployment's callback URL as the ABDM bridge URL. "
        "Defaults to ABDM_CALLBACK_BASE_URL + ABDM_CALLBACK_PATH_PREFIX."
    )

    def add_arguments(self, parser):
        parser.add_argument("--url", help="Register this URL instead of the default.")
        parser.add_argument(
            "--check",
            action="store_true",
            help="Only show the registered and expected URLs; change nothing.",
        )

    def handle(self, *args, **options):
        url = (options["url"] or bridge.expected_bridge_url()).rstrip("/")
        if not url:
            msg = "Set ABDM_CALLBACK_BASE_URL or pass --url."
            raise CommandError(msg)
        current = _registered_url()
        self.stdout.write(f"Registered: {current or '(none)'}")
        self.stdout.write(f"Expected:   {url}")
        if options["check"]:
            return
        if current.rstrip("/") == url:
            self.stdout.write(self.style.SUCCESS("Already registered."))
            return

        row = bridge.update_bridge_url(url)
        if not row.ok:
            msg = f"ABDM refused: {row.error_code} {row.error_message} (ref {row.request_id})"
            raise CommandError(msg)
        self.stdout.write(
            self.style.SUCCESS(
                f"Registered (ref {row.request_id}). The previous URL was {current or '(none)'}. "
                "Callbacks can keep going to the old URL for a few minutes."
            )
        )
"}
